    { r = {"MACBETH"}, t = "Why hath it given me earnest of success," },
    { r = {"MACBETH"}, t = "Commencing in a truth? I am Thane of Cawdor:" },
    { r = {"MACBETH"}, t = "If good, why do I yield to that suggestion" },
    { r = {"MACBETH"}, t = "Whose horrid image doth unfix my hair," },
    { r = {"MACBETH"}, t = "And make my seated heart knock at my ribs," },
    { r = {"MACBETH"}, t = "Against the use of nature? Present fears" },
    { r = {"MACBETH"}, t = "Are less than horrible imaginings." },
    { r = {"MACBETH"}, t = "My thought, whose murder yet is but fantastical," },
    { r = {"MACBETH"}, t = "Shakes so my single state of man" },
    { r = {"MACBETH"}, t = "That function is smother’d in surmise," },
    { r = {"MACBETH"}, t = "And nothing is but what is not." },
    { r = {"BANQUO"}, t = "Look, how our partner’s rapt." },
    { r = {"MACBETH"}, t = "If chance will have me king, why, chance may crown me", d = "Aside" },
    { r = {"MACBETH"}, t = "Without my stir." },
    { r = {"BANQUO"}, t = "New honours come upon him," },
    { r = {"BANQUO"}, t = "Like our strange garments, cleave not to their mould" },
    { r = {"BANQUO"}, t = "But with the aid of use." },
    { r = {"MACBETH"}, t = "Come what come may,", d = "Aside" },
    { r = {"MACBETH"}, t = "Time and the hour runs through the roughest day." },
    { r = {"BANQUO"}, t = "Worthy Macbeth, we stay upon your leisure." },
    { r = {"MACBETH"}, t = "Give me your favour. My dull brain was wrought" },
    { r = {"MACBETH"}, t = "With things forgotten. Kind gentlemen, your pains" },
    { r = {"MACBETH"}, t = "Are register’d where every day I turn" },
    { r = {"MACBETH"}, t = "The leaf to read them.—Let us toward the King.—" },
    { r = {"MACBETH"}, t = "Think upon what hath chanc’d; and at more time," },
    { r = {"MACBETH"}, t = "The interim having weigh’d it, let us speak" },
    { r = {"MACBETH"}, t = "Our free hearts each to other." },
    { r = {"BANQUO"}, t = "Very gladly." },
    { r = {"MACBETH"}, t = "Till then, enough.—Come, friends." },
    { d = "Exeunt" },
    { d = "Act 1, Scene 4. Forres. A Room in the Palace.", h = true },
    { d = "Flourish. Enter Duncan, Malcolm, Donalbain, Lennox and Attendants" },
    { r = {"DUNCAN"}, t = "Is execution done on Cawdor? Are not" },
    { r = {"DUNCAN"}, t = "Those in commission yet return’d?" },
    { r = {"MALCOLM"}, t = "My liege," },
    { r = {"MALCOLM"}, t = "They are not yet come back. But I have spoke" },
    { r = {"MALCOLM"}, t = "With one that saw him die, who did report," },
    { r = {"MALCOLM"}, t = "That very frankly he confess’d his treasons," },
    { r = {"MALCOLM"}, t = "Implor’d your Highness’ pardon, and set forth" },
    { r = {"MALCOLM"}, t = "A deep repentance. Nothing in his life" },
    { r = {"MALCOLM"}, t = "Became him like the leaving it; he died" },
    { r = {"MALCOLM"}, t = "As one that had been studied in his death," },
    { r = {"MALCOLM"}, t = "To throw away the dearest thing he ow’d" },
    { r = {"MALCOLM"}, t = "As ’twere a careless trifle." },
    { r = {"DUNCAN"}, t = "There’s no art" },
    { r = {"DUNCAN"}, t = "To find the mind’s construction in the face:" },
    { r = {"DUNCAN"}, t = "He was a gentleman on whom I built" },
    { r = {"DUNCAN"}, t = "An absolute trust." },
    { d = "Enter Macbeth, Banquo, Ross and Angus" },
    { r = {"DUNCAN"}, t = "O worthiest cousin!" },
    { r = {"DUNCAN"}, t = "The sin of my ingratitude even now" },
    { r = {"DUNCAN"}, t = "Was heavy on me. Thou art so far before," },
    { r = {"DUNCAN"}, t = "That swiftest wing of recompense is slow" },
    { r = {"DUNCAN"}, t = "To overtake thee. Would thou hadst less deserv’d;" },
    { r = {"DUNCAN"}, t = "That the proportion both of thanks and payment" },
    { r = {"DUNCAN"}, t = "Might have been mine! only I have left to say," },
    { r = {"DUNCAN"}, t = "More is thy due than more than all can pay." },
    { r = {"MACBETH"}, t = "The service and the loyalty I owe," },
    { r = {"MACBETH"}, t = "In doing it, pays itself. Your Highness’ part" },
    { r = {"MACBETH"}, t = "Is to receive our duties: and our duties" },
    { r = {"MACBETH"}, t = "Are to your throne and state, children and servants;" },
    { r = {"MACBETH"}, t = "Which do but what they should, by doing everything" },
    { r = {"MACBETH"}, t = "Safe toward your love and honour." },
    { r = {"DUNCAN"}, t = "Welcome hither:" },
    { r = {"DUNCAN"}, t = "I have begun to plant thee, and will labour" },
    { r = {"DUNCAN"}, t = "To make thee full of growing.—Noble Banquo," },
    { r = {"DUNCAN"}, t = "That hast no less deserv’d, nor must be known" },
    { r = {"DUNCAN"}, t = "No less to have done so, let me infold thee" },
    { r = {"DUNCAN"}, t = "And hold thee to my heart." },
    { r = {"BANQUO"}, t = "There if I grow," },
    { r = {"BANQUO"}, t = "The harvest is your own." },
    { r = {"DUNCAN"}, t = "My plenteous joys," },
    { r = {"DUNCAN"}, t = "Wanton in fulness, seek to hide themselves" },
    { r = {"DUNCAN"}, t = "In drops of sorrow.—Sons, kinsmen, thanes," },
    { r = {"DUNCAN"}, t = "And you whose places are the nearest, know," },
    { r = {"DUNCAN"}, t = "We will establish our estate upon" },
    { r = {"DUNCAN"}, t = "Our eldest, Malcolm; whom we name hereafter" },
    { r = {"DUNCAN"}, t = "The Prince of Cumberland: which honour must" },
    { r = {"DUNCAN"}, t = "Not unaccompanied invest him only," },
    { r = {"DUNCAN"}, t = "But signs of nobleness, like stars, shall shine" },
    { r = {"DUNCAN"}, t = "On all deservers.—From hence to Inverness," },
    { r = {"DUNCAN"}, t = "And bind us further to you." },
    { r = {"MACBETH"}, t = "The rest is labour, which is not us’d for you:" },
    { r = {"MACBETH"}, t = "I’ll be myself the harbinger, and make joyful" },
    { r = {"MACBETH"}, t = "The hearing of my wife with your approach;" },
    { r = {"MACBETH"}, t = "So, humbly take my leave." },
    { r = {"DUNCAN"}, t = "My worthy Cawdor!" },
    { r = {"MACBETH"}, t = "The Prince of Cumberland!—That is a step", d = "Aside" },
    { r = {"MACBETH"}, t = "On which I must fall down, or else o’erleap," },
    { r = {"MACBETH"}, t = "For in my way it lies. Stars, hide your fires!" },
    { r = {"MACBETH"}, t = "Let not light see my black and deep desires." },
    { r = {"MACBETH"}, t = "The eye wink at the hand, yet let that be," },
    { r = {"MACBETH"}, t = "Which the eye fears, when it is done, to see." },
    { d = "Exit" },
    { r = {"DUNCAN"}, t = "True, worthy Banquo! He is full so valiant;" },
    { r = {"DUNCAN"}, t = "And in his commendations I am fed." },
    { r = {"DUNCAN"}, t = "It is a banquet to me. Let’s after him," },
    { r = {"DUNCAN"}, t = "Whose care is gone before to bid us welcome:" },
    { r = {"DUNCAN"}, t = "It is a peerless kinsman." },
    { d = "Flourish. Exeunt" },
    { d = "Act 1, Scene 5. Inverness. A Room in Macbeth’s Castle.", h = true },
    { d = "Enter Lady Macbeth, reading a letter" },
    { r = {"LADY MACBETH"}, t = "“They met me in the day of success; and I have learned by the perfect’st report they have more in them than mortal knowledge." },
    { r = {"LADY MACBETH"}, t = "When I burned in desire to question them further, they made themselves air, into which they vanished." },
    { r = {"LADY MACBETH"}, t = "Whiles I stood rapt in the wonder of it, came missives from the King, who all-hailed me, ‘Thane of Cawdor’; by which title, before, these Weird Sisters saluted me, and referred me to the coming on of time, with ‘Hail, king that shalt be!’" },
    { r = {"LADY MACBETH"}, t = "This have I thought good to deliver thee (my dearest partner of greatness) that thou might’st not lose the dues of rejoicing, by being ignorant of what greatness is promis’d thee." },
    { r = {"LADY MACBETH"}, t = "Lay it to thy heart, and farewell.”" },
    { r = {"LADY MACBETH"}, t = "Glamis thou art, and Cawdor; and shalt be" },
    { r = {"LADY MACBETH"}, t = "What thou art promis’d. Yet do I fear thy nature;" },
    { r = {"LADY MACBETH"}, t = "It is too full o’ th’ milk of human kindness" },
    { r = {"LADY MACBETH"}, t = "To catch the nearest way. Thou wouldst be great;" },
    { r = {"LADY MACBETH"}, t = "Art not without ambition, but without" },
    { r = {"LADY MACBETH"}, t = "The illness should attend it. What thou wouldst highly," },
    { r = {"LADY MACBETH"}, t = "That wouldst thou holily; wouldst not play false," },
    { r = {"LADY MACBETH"}, t = "And yet wouldst wrongly win. Thou’dst have, great Glamis," },
    { r = {"LADY MACBETH"}, t = "That which cries, “Thus thou must do,” if thou have it;" },
    { r = {"LADY MACBETH"}, t = "And that which rather thou dost fear to do," },
    { r = {"LADY MACBETH"}, t = "Than wishest should be undone. Hie thee hither," },
    { r = {"LADY MACBETH"}, t = "That I may pour my spirits in thine ear," },
    { r = {"LADY MACBETH"}, t = "And chastise with the valour of my tongue" },
    { r = {"LADY MACBETH"}, t = "All that impedes thee from the golden round," },
    { r = {"LADY MACBETH"}, t = "Which fate and metaphysical aid doth seem" },
    { r = {"LADY MACBETH"}, t = "To have thee crown’d withal." },
    { d = "Enter a Messenger" },
    { r = {"LADY MACBETH"}, t = "What is your tidings?" },
    { r = {"MESSENGER"}, t = "The King comes here tonight." },
    { r = {"LADY MACBETH"}, t = "Thou’rt mad to say it." },
    { r = {"LADY MACBETH"}, t = "Is not thy master with him? who, were’t so," },
    { r = {"LADY MACBETH"}, t = "Would have inform’d for preparation." },
    { r = {"MESSENGER"}, t = "So please you, it is true. Our thane is coming." },
    { r = {"MESSENGER"}, t = "One of my fellows had the speed of him," },
    { r = {"MESSENGER"}, t = "Who, almost dead for breath, had scarcely more" },
    { r = {"MESSENGER"}, t = "Than would make up his message." },
    { r = {"LADY MACBETH"}, t = "Give him tending." },
    { r = {"LADY MACBETH"}, t = "He brings great news." },
    { d = "Exit Messenger" },
    { r = {"LADY MACBETH"}, t = "The raven himself is hoarse" },
    { r = {"LADY MACBETH"}, t = "That croaks the fatal entrance of Duncan" },
    { r = {"LADY MACBETH"}, t = "Under my battlements. Come, you spirits" },
    { r = {"LADY MACBETH"}, t = "That tend on mortal thoughts, unsex me here," },
    { r = {"LADY MACBETH"}, t = "And fill me, from the crown to the toe, top-full" },
    { r = {"LADY MACBETH"}, t = "Of direst cruelty! make thick my blood," },
    { r = {"LADY MACBETH"}, t = "Stop up th’ access and passage to remorse," },
    { r = {"LADY MACBETH"}, t = "That no compunctious visitings of nature" },
    { r = {"LADY MACBETH"}, t = "Shake my fell purpose, nor keep peace between" },
    { r = {"LADY MACBETH"}, t = "Th’ effect and it! Come to my woman’s breasts," },
    { r = {"LADY MACBETH"}, t = "And take my milk for gall, your murd’ring ministers," },
    { r = {"LADY MACBETH"}, t = "Wherever in your sightless substances" },
    { r = {"LADY MACBETH"}, t = "You wait on nature’s mischief! Come, thick night," },
    { r = {"LADY MACBETH"}, t = "And pall thee in the dunnest smoke of hell" },
    { r = {"LADY MACBETH"}, t = "That my keen knife see not the wound it makes," },
    { r = {"LADY MACBETH"}, t = "Nor heaven peep through the blanket of the dark" },
    { r = {"LADY MACBETH"}, t = "To cry, “Hold, hold!”" },
    { d = "Enter Macbeth" },
    { r = {"LADY MACBETH"}, t = "Great Glamis, worthy Cawdor!" },
    { r = {"LADY MACBETH"}, t = "Greater than both, by the all-hail hereafter!" },
    { r = {"LADY MACBETH"}, t = "Thy letters have transported me beyond" },
    { r = {"LADY MACBETH"}, t = "This ignorant present, and I feel now" },
    { r = {"LADY MACBETH"}, t = "The future in the instant." },
    { r = {"MACBETH"}, t = "My dearest love," },
    { r = {"MACBETH"}, t = "Duncan comes here tonight." },
    { r = {"LADY MACBETH"}, t = "And when goes hence?" },
    { r = {"MACBETH"}, t = "Tomorrow, as he purposes." },
    { r = {"LADY MACBETH"}, t = "O, never" },
    { r = {"LADY MACBETH"}, t = "Shall sun that morrow see!" },
    { r = {"LADY MACBETH"}, t = "Your face, my thane, is as a book where men" },
    { r = {"LADY MACBETH"}, t = "May read strange matters. To beguile the time," },
    { r = {"LADY MACBETH"}, t = "Look like the time; bear welcome in your eye," },
    { r = {"LADY MACBETH"}, t = "Your hand, your tongue: look like the innocent flower," },
    { r = {"LADY MACBETH"}, t = "But be the serpent under’t. He that’s coming" },
    { r = {"LADY MACBETH"}, t = "Must be provided for; and you shall put" },
    { r = {"LADY MACBETH"}, t = "This night’s great business into my dispatch;" },
    { r = {"LADY MACBETH"}, t = "Which shall to all our nights and days to come" },
    { r = {"LADY MACBETH"}, t = "Give solely sovereign sway and masterdom." },
    { r = {"MACBETH"}, t = "We will speak further." },
    { r = {"LADY MACBETH"}, t = "Only look up clear;" },
    { r = {"LADY MACBETH"}, t = "To alter favour ever is to fear." },
    { r = {"LADY MACBETH"}, t = "Leave all the rest to me." },
    { d = "Exeunt" },
    { d = "Act 1, Scene 6. The same. Before the Castle.", h = true },
    { d = "Hautboys. Servants of Macbeth attending" },
    { d = "Enter Duncan, Malcolm, Donalbain, Banquo, Lennox, Macduff, Ross, Angus and Attendants" },
    { r = {"DUNCAN"}, t = "This castle hath a pleasant seat. The air" },
    { r = {"DUNCAN"}, t = "Nimbly and sweetly recommends itself" },
    { r = {"DUNCAN"}, t = "Unto our gentle senses." },
    { r = {"BANQUO"}, t = "This guest of summer," },
    { r = {"BANQUO"}, t = "The temple-haunting martlet, does approve," },
    { r = {"BANQUO"}, t = "By his loved mansionry, that the heaven’s breath" },
    { r = {"BANQUO"}, t = "Smells wooingly here: no jutty, frieze," },
    { r = {"BANQUO"}, t = "Buttress, nor coign of vantage, but this bird hath made his pendant bed and procreant cradle." },
    { r = {"BANQUO"}, t = "Where they most breed and haunt, I have observ’d" },
    { r = {"BANQUO"}, t = "The air is delicate." },
    { d = "Enter Lady Macbeth" },
    { r = {"DUNCAN"}, t = "See, see, our honour’d hostess!—" },
    { r = {"DUNCAN"}, t = "The love that follows us sometime is our trouble," },
    { r = {"DUNCAN"}, t = "Which still we thank as love. Herein I teach you" },
    { r = {"DUNCAN"}, t = "How you shall bid God ’ild us for your pains," },
    { r = {"DUNCAN"}, t = "And thank us for your trouble." },
    { r = {"LADY MACBETH"}, t = "All our service," },
    { r = {"LADY MACBETH"}, t = "In every point twice done, and then done double," },
    { r = {"LADY MACBETH"}, t = "Were poor and single business to contend" },
    { r = {"LADY MACBETH"}, t = "Against those honours deep and broad wherewith" },
    { r = {"LADY MACBETH"}, t = "Your Majesty loads our house: for those of old," },
    { r = {"LADY MACBETH"}, t = "And the late dignities heap’d up to them," },
    { r = {"LADY MACBETH"}, t = "We rest your hermits." },
    { r = {"DUNCAN"}, t = "Where’s the Thane of Cawdor?" },
    { r = {"DUNCAN"}, t = "We cours’d him at the heels, and had a purpose" },
    { r = {"DUNCAN"}, t = "To be his purveyor: but he rides well;" },
    { r = {"DUNCAN"}, t = "And his great love, sharp as his spur, hath holp him" },
    { r = {"DUNCAN"}, t = "To his home before us. Fair and noble hostess," },
    { r = {"DUNCAN"}, t = "We are your guest tonight." },
    { r = {"LADY MACBETH"}, t = "Your servants ever" },
    { r = {"LADY MACBETH"}, t = "Have theirs, themselves, and what is theirs, in compt," },
    { r = {"LADY MACBETH"}, t = "To make their audit at your Highness’ pleasure," },
    { r = {"LADY MACBETH"}, t = "Still to return your own." },
    { r = {"DUNCAN"}, t = "Give me your hand;" },
    { r = {"DUNCAN"}, t = "Conduct me to mine host: we love him highly," },
    { r = {"DUNCAN"}, t = "And shall continue our graces towards him." },
    { r = {"DUNCAN"}, t = "By your leave, hostess." },
    { d = "Exeunt" },
    { d = "Act 1, Scene 7. The same. A Lobby in the Castle.", h = true },
    { d = "Hautboys and torches. Enter, and pass over, a Sewer and divers Servants with dishes and service. Then enter Macbeth" },
    { r = {"MACBETH"}, t = "If it were done when ’tis done, then ’twere well" },
    { r = {"MACBETH"}, t = "It were done quickly. If th’ assassination" },
    { r = {"MACBETH"}, t = "Could trammel up the consequence, and catch" },
    { r = {"MACBETH"}, t = "With his surcease success; that but this blow" },
    { r = {"MACBETH"}, t = "Might be the be-all and the end-all—here," },
    { r = {"MACBETH"}, t = "But here, upon this bank and shoal of time," },
    { r = {"MACBETH"}, t = "We’d jump the life to come. But in these cases" },
    { r = {"MACBETH"}, t = "We still have judgement here; that we but teach" },
    { r = {"MACBETH"}, t = "Bloody instructions, which being taught, return" },
    { r = {"MACBETH"}, t = "To plague th’ inventor. This even-handed justice" },
    { r = {"MACBETH"}, t = "Commends th’ ingredience of our poison’d chalice" },
    { r = {"MACBETH"}, t = "To our own lips. He’s here in double trust:" },
    { r = {"MACBETH"}, t = "First, as I am his kinsman and his subject," },
    { r = {"MACBETH"}, t = "Strong both against the deed; then, as his host," },
    { r = {"MACBETH"}, t = "Who should against his murderer shut the door," },
    { r = {"MACBETH"}, t = "Not bear the knife myself. Besides, this Duncan" },
    { r = {"MACBETH"}, t = "Hath borne his faculties so meek, hath been" },
    { r = {"MACBETH"}, t = "So clear in his great office, that his virtues" },
    { r = {"MACBETH"}, t = "Will plead like angels, trumpet-tongued, against" },
    { r = {"MACBETH"}, t = "The deep damnation of his taking-off;" },
    { r = {"MACBETH"}, t = "And pity, like a naked new-born babe," },
    { r = {"MACBETH"}, t = "Striding the blast, or heaven’s cherubin, hors’d" },
    { r = {"MACBETH"}, t = "Upon the sightless couriers of the air," },
    { r = {"MACBETH"}, t = "Shall blow the horrid deed in every eye," },
    { r = {"MACBETH"}, t = "That tears shall drown the wind.—I have no spur" },
    { r = {"MACBETH"}, t = "To prick the sides of my intent, but only" },
    { r = {"MACBETH"}, t = "Vaulting ambition, which o’erleaps itself" },
    { r = {"MACBETH"}, t = "And falls on th’ other" },
    { d = "Enter Lady Macbeth" },
    { r = {"MACBETH"}, t = "How now! what news?" },
    { r = {"LADY MACBETH"}, t = "He has almost supp’d. Why have you left the chamber?" },
    { r = {"MACBETH"}, t = "Hath he ask’d for me?" },
    { r = {"LADY MACBETH"}, t = "Know you not he has?" },
    { r = {"MACBETH"}, t = "We will proceed no further in this business:" },
    { r = {"MACBETH"}, t = "He hath honour’d me of late; and I have bought" },
    { r = {"MACBETH"}, t = "Golden opinions from all sorts of people," },
    { r = {"MACBETH"}, t = "Which would be worn now in their newest gloss," },
    { r = {"MACBETH"}, t = "Not cast aside so soon." },
    { r = {"LADY MACBETH"}, t = "Was the hope drunk" },
    { r = {"LADY MACBETH"}, t = "Wherein you dress’d yourself? Hath it slept since?" },
    { r = {"LADY MACBETH"}, t = "And wakes it now, to look so green and pale" },
    { r = {"LADY MACBETH"}, t = "At what it did so freely? From this time" },
    { r = {"LADY MACBETH"}, t = "Such I account thy love. Art thou afeard" },
    { r = {"LADY MACBETH"}, t = "To be the same in thine own act and valour" },
    { r = {"LADY MACBETH"}, t = "As thou art in desire? Wouldst thou have that" },
    { r = {"LADY MACBETH"}, t = "Which thou esteem’st the ornament of life," },
    { r = {"LADY MACBETH"}, t = "And live a coward in thine own esteem," },
    { r = {"LADY MACBETH"}, t = "Letting “I dare not” wait upon “I would,”" },
    { r = {"LADY MACBETH"}, t = "Like the poor cat i’ th’ adage?" },
    { r = {"MACBETH"}, t = "Pr’ythee, peace!" },
    { r = {"MACBETH"}, t = "I dare do all that may become a man;" },
    { r = {"MACBETH"}, t = "Who dares do more is none." },
    { r = {"LADY MACBETH"}, t = "What beast was’t, then," },
    { r = {"LADY MACBETH"}, t = "That made you break this enterprise to me?" },
    { r = {"LADY MACBETH"}, t = "When you durst do it, then you were a man;" },
    { r = {"LADY MACBETH"}, t = "And, to be more than what you were, you would" },
    { r = {"LADY MACBETH"}, t = "Be so much more the man. Nor time nor place" },
    { r = {"LADY MACBETH"}, t = "Did then adhere, and yet you would make both:" },
    { r = {"LADY MACBETH"}, t = "They have made themselves, and that their fitness now" },
    { r = {"LADY MACBETH"}, t = "Does unmake you. I have given suck, and know" },
    { r = {"LADY MACBETH"}, t = "How tender ’tis to love the babe that milks me:" },
    { r = {"LADY MACBETH"}, t = "I would, while it was smiling in my face," },
    { r = {"LADY MACBETH"}, t = "Have pluck’d my nipple from his boneless gums" },
    { r = {"LADY MACBETH"}, t = "And dash’d the brains out, had I so sworn as you" },
    { r = {"LADY MACBETH"}, t = "Have done to this." },
    { r = {"MACBETH"}, t = "If we should fail?" },
    { r = {"LADY MACBETH"}, t = "We fail?" },
    { r = {"LADY MACBETH"}, t = "But screw your courage to the sticking-place," },
    { r = {"LADY MACBETH"}, t = "And we’ll not fail. When Duncan is asleep" },
    { r = {"LADY MACBETH"}, t = "(Whereto the rather shall his day’s hard journey" },
    { r = {"LADY MACBETH"}, t = "Soundly invite him), his two chamberlains" },
    { r = {"LADY MACBETH"}, t = "Will I with wine and wassail so convince" },
    { r = {"LADY MACBETH"}, t = "That memory, the warder of the brain," },
    { r = {"LADY MACBETH"}, t = "Shall be a fume, and the receipt of reason" },
    { r = {"LADY MACBETH"}, t = "A limbeck only: when in swinish sleep" },
    { r = {"LADY MACBETH"}, t = "Their drenched natures lie as in a death," },
    { r = {"LADY MACBETH"}, t = "What cannot you and I perform upon" },
    { r = {"LADY MACBETH"}, t = "Th’ unguarded Duncan? what not put upon" },
    { r = {"LADY MACBETH"}, t = "His spongy officers; who shall bear the guilt" },
    { r = {"LADY MACBETH"}, t = "Of our great quell?" },
    { r = {"MACBETH"}, t = "Bring forth men-children only;" },
    { r = {"MACBETH"}, t = "For thy undaunted mettle should compose" },
    { r = {"MACBETH"}, t = "Nothing but males. Will it not be receiv’d," },
    { r = {"MACBETH"}, t = "When we have mark’d with blood those sleepy two" },
    { r = {"MACBETH"}, t = "Of his own chamber, and us’d their very daggers," },
    { r = {"MACBETH"}, t = "That they have done’t?" },
    { r = {"LADY MACBETH"}, t = "Who dares receive it other," },
    { r = {"LADY MACBETH"}, t = "As we shall make our griefs and clamour roar" },
    { r = {"LADY MACBETH"}, t = "Upon his death?" },
    { r = {"MACBETH"}, t = "I am settled, and bend up" },
    { r = {"MACBETH"}, t = "Each corporal agent to this terrible feat." },
    { r = {"MACBETH"}, t = "Away, and mock the time with fairest show:" },
    { r = {"MACBETH"}, t = "False face must hide what the false heart doth know." },
    { d = "Exeunt" },
    { d = "Act 2, Scene 1. Inverness. Court within the Castle.", h = true },
    { d = "Enter Banquo and Fleance with a torch before him" },
    { r = {"BANQUO"}, t = "How goes the night, boy?" },
    { r = {"FLEANCE"}, t = "The moon is down; I have not heard the clock." },
    { r = {"BANQUO"}, t = "And she goes down at twelve." },
    { r = {"FLEANCE"}, t = "I take’t, ’tis later, sir." },
    { r = {"BANQUO"}, t = "Hold, take my sword.—There’s husbandry in heaven;" },
    { r = {"BANQUO"}, t = "Their candles are all out. Take thee that too." },
    { r = {"BANQUO"}, t = "A heavy summons lies like lead upon me," },
    { r = {"BANQUO"}, t = "And yet I would not sleep. Merciful powers," },
    { r = {"BANQUO"}, t = "Restrain in me the cursed thoughts that nature" },
    { r = {"BANQUO"}, t = "Gives way to in repose!" },
    { d = "Enter Macbeth and a Servant with a torch" },
    { r = {"BANQUO"}, t = "Give me my sword.—Who’s there?" },
    { r = {"MACBETH"}, t = "A friend." },
    { r = {"BANQUO"}, t = "What, sir, not yet at rest? The King’s abed:" },
    { r = {"BANQUO"}, t = "He hath been in unusual pleasure and" },
    { r = {"BANQUO"}, t = "Sent forth great largess to your offices." },
    { r = {"BANQUO"}, t = "This diamond he greets your wife withal," },
    { r = {"BANQUO"}, t = "By the name of most kind hostess, and shut up" },
    { r = {"BANQUO"}, t = "In measureless content." },
    { r = {"MACBETH"}, t = "Being unprepar’d," },
    { r = {"MACBETH"}, t = "Our will became the servant to defect," },
    { r = {"MACBETH"}, t = "Which else should free have wrought." },
    { r = {"BANQUO"}, t = "All’s well." },
    { r = {"BANQUO"}, t = "I dreamt last night of the three Weird Sisters:" },
    { r = {"BANQUO"}, t = "To you they have show’d some truth." },
    { r = {"MACBETH"}, t = "I think not of them:" },
    { r = {"MACBETH"}, t = "Yet, when we can entreat an hour to serve," },
    { r = {"MACBETH"}, t = "We would spend it in some words upon that business," },
    { r = {"MACBETH"}, t = "If you would grant the time." },
    { r = {"BANQUO"}, t = "At your kind’st leisure." },
    { r = {"MACBETH"}, t = "If you shall cleave to my consent, when ’tis," },
    { r = {"MACBETH"}, t = "It shall make honour for you." },
    { r = {"BANQUO"}, t = "So I lose none" },
    { r = {"BANQUO"}, t = "In seeking to augment it, but still keep" },
    { r = {"BANQUO"}, t = "My bosom franchis’d, and allegiance clear," },
    { r = {"BANQUO"}, t = "I shall be counsell’d." },
    { r = {"MACBETH"}, t = "Good repose the while!" },
    { r = {"BANQUO"}, t = "Thanks, sir: the like to you." },
    { d = "Exeunt Banquo and Fleance" },
    { r = {"MACBETH"}, t = "Go bid thy mistress, when my drink is ready," },
    { r = {"MACBETH"}, t = "She strike upon the bell. Get thee to bed." },
    { d = "Exit Servant" },
    { r = {"MACBETH"}, t = "Is this a dagger which I see before me," },
    { r = {"MACBETH"}, t = "The handle toward my hand? Come, let me clutch thee:—" },
    { r = {"MACBETH"}, t = "I have thee not, and yet I see thee still." },
    { r = {"MACBETH"}, t = "Art thou not, fatal vision, sensible" },
    { r = {"MACBETH"}, t = "To feeling as to sight? or art thou but" },
    { r = {"MACBETH"}, t = "A dagger of the mind, a false creation," },
    { r = {"MACBETH"}, t = "Proceeding from the heat-oppressed brain?" },
    { r = {"MACBETH"}, t = "I see thee yet, in form as palpable" },
    { r = {"MACBETH"}, t = "As this which now I draw." },
    { r = {"MACBETH"}, t = "Thou marshall’st me the way that I was going;" },
    { r = {"MACBETH"}, t = "And such an instrument I was to use." },
    { r = {"MACBETH"}, t = "Mine eyes are made the fools o’ the other senses," },
    { r = {"MACBETH"}, t = "Or else worth all the rest: I see thee still;" },
    { r = {"MACBETH"}, t = "And on thy blade and dudgeon, gouts of blood," },
    { r = {"MACBETH"}, t = "Which was not so before.—There’s no such thing." },
    { r = {"MACBETH"}, t = "It is the bloody business which informs" },
    { r = {"MACBETH"}, t = "Thus to mine eyes.—Now o’er the one half-world" },
    { r = {"MACBETH"}, t = "Nature seems dead, and wicked dreams abuse" },
    { r = {"MACBETH"}, t = "The curtain’d sleep. Witchcraft celebrates" },
    { r = {"MACBETH"}, t = "Pale Hecate’s off’rings; and wither’d murder," },
    { r = {"MACBETH"}, t = "Alarum’d by his sentinel, the wolf," },
    { r = {"MACBETH"}, t = "Whose howl’s his watch, thus with his stealthy pace," },
    { r = {"MACBETH"}, t = "With Tarquin’s ravishing strides, towards his design" },
    { r = {"MACBETH"}, t = "Moves like a ghost.—Thou sure and firm-set earth," },
    { r = {"MACBETH"}, t = "Hear not my steps, which way they walk, for fear" },
    { r = {"MACBETH"}, t = "Thy very stones prate of my whereabout," },
    { r = {"MACBETH"}, t = "And take the present horror from the time," },
    { r = {"MACBETH"}, t = "Which now suits with it.—Whiles I threat, he lives." },
    { r = {"MACBETH"}, t = "Words to the heat of deeds too cold breath gives." },
    { d = "A bell rings" },
    { r = {"MACBETH"}, t = "I go, and it is done. The bell invites me." },
    { r = {"MACBETH"}, t = "Hear it not, Duncan, for it is a knell" },
    { r = {"MACBETH"}, t = "That summons thee to heaven or to hell." },
    { d = "Exit" },
    { d = "Act 2, Scene 2. The same.", h = true },
    { d = "Enter Lady Macbeth" },
    { r = {"LADY MACBETH"}, t = "That which hath made them drunk hath made me bold:" },
    { r = {"LADY MACBETH"}, t = "What hath quench’d them hath given me fire.—Hark!—Peace!" },
    { r = {"LADY MACBETH"}, t = "It was the owl that shriek’d, the fatal bellman," },
    { r = {"LADY MACBETH"}, t = "Which gives the stern’st good night. He is about it." },
    { r = {"LADY MACBETH"}, t = "The doors are open; and the surfeited grooms" },
    { r = {"LADY MACBETH"}, t = "Do mock their charge with snores: I have drugg’d their possets, That death and nature do contend about them," },
    { r = {"LADY MACBETH"}, t = "Whether they live or die." },
    { r = {"MACBETH"}, t = "Who’s there?—what, ho!", d = "Within" },
    { r = {"LADY MACBETH"}, t = "Alack! I am afraid they have awak’d," },
    { r = {"LADY MACBETH"}, t = "And ’tis not done. Th’ attempt and not the deed" },
    { r = {"LADY MACBETH"}, t = "Confounds us.—Hark!—I laid their daggers ready;" },
    { r = {"LADY MACBETH"}, t = "He could not miss ’em.—Had he not resembled" },
    { r = {"LADY MACBETH"}, t = "My father as he slept, I had done’t.—My husband!" },
    { d = "Enter Macbeth" },
    { r = {"MACBETH"}, t = "I have done the deed.—Didst thou not hear a noise?" },
    { r = {"LADY MACBETH"}, t = "I heard the owl scream and the crickets cry." },
    { r = {"LADY MACBETH"}, t = "Did not you speak?" },
    { r = {"MACBETH"}, t = "When?" },
    { r = {"LADY MACBETH"}, t = "Now." },
    { r = {"MACBETH"}, t = "As I descended?" },
    { r = {"LADY MACBETH"}, t = "Ay." },
    { r = {"MACBETH"}, t = "Hark!—Who lies i’ th’ second chamber?" },
    { r = {"LADY MACBETH"}, t = "Donalbain." },
    { r = {"MACBETH"}, t = "This is a sorry sight." },
    { d = "Looking on his hands" },
    { r = {"LADY MACBETH"}, t = "A foolish thought, to say a sorry sight." },
    { r = {"MACBETH"}, t = "There’s one did laugh in’s sleep, and one cried, “Murder!”" },
    { r = {"MACBETH"}, t = "That they did wake each other: I stood and heard them." },
    { r = {"MACBETH"}, t = "But they did say their prayers, and address’d them" },
    { r = {"MACBETH"}, t = "Again to sleep." },
    { r = {"LADY MACBETH"}, t = "There are two lodg’d together." },
    { r = {"MACBETH"}, t = "One cried, “God bless us!” and, “Amen,” the other," },
    { r = {"MACBETH"}, t = "As they had seen me with these hangman’s hands." },
    { r = {"MACBETH"}, t = "List’ning their fear, I could not say “Amen,”" },
    { r = {"MACBETH"}, t = "When they did say, “God bless us.”" },
    { r = {"LADY MACBETH"}, t = "Consider it not so deeply." },
    { r = {"MACBETH"}, t = "But wherefore could not I pronounce “Amen”?" },
    { r = {"MACBETH"}, t = "I had most need of blessing, and “Amen”" },
    { r = {"MACBETH"}, t = "Stuck in my throat." },
    { r = {"LADY MACBETH"}, t = "These deeds must not be thought" },
    { r = {"LADY MACBETH"}, t = "After these ways; so, it will make us mad." },
    { r = {"MACBETH"}, t = "Methought I heard a voice cry, “Sleep no more!" },
    { r = {"MACBETH"}, t = "Macbeth does murder sleep,”—the innocent sleep;" },
    { r = {"MACBETH"}, t = "Sleep that knits up the ravell’d sleave of care," },
    { r = {"MACBETH"}, t = "The death of each day’s life, sore labour’s bath," },
    { r = {"MACBETH"}, t = "Balm of hurt minds, great nature’s second course," },
    { r = {"MACBETH"}, t = "Chief nourisher in life’s feast." },
    { r = {"LADY MACBETH"}, t = "What do you mean?" },
    { r = {"MACBETH"}, t = "Still it cried, “Sleep no more!” to all the house:" },
    { r = {"MACBETH"}, t = "“Glamis hath murder’d sleep, and therefore Cawdor" },
    { r = {"MACBETH"}, t = "Shall sleep no more. Macbeth shall sleep no more!”" },
    { r = {"LADY MACBETH"}, t = "Who was it that thus cried? Why, worthy thane," },
    { r = {"LADY MACBETH"}, t = "You do unbend your noble strength to think" },
    { r = {"LADY MACBETH"}, t = "So brainsickly of things. Go get some water," },
    { r = {"LADY MACBETH"}, t = "And wash this filthy witness from your hand.—" },
    { r = {"LADY MACBETH"}, t = "Why did you bring these daggers from the place?" },
    { r = {"LADY MACBETH"}, t = "They must lie there: go carry them, and smear" },
    { r = {"LADY MACBETH"}, t = "The sleepy grooms with blood." },
    { r = {"MACBETH"}, t = "I’ll go no more:" },
    { r = {"MACBETH"}, t = "I am afraid to think what I have done;" },
    { r = {"MACBETH"}, t = "Look on’t again I dare not." },
    { r = {"LADY MACBETH"}, t = "Infirm of purpose!" },
    { r = {"LADY MACBETH"}, t = "Give me the daggers. The sleeping and the dead" },
    { r = {"LADY MACBETH"}, t = "Are but as pictures. ’Tis the eye of childhood" },
    { r = {"LADY MACBETH"}, t = "That fears a painted devil. If he do bleed," },
    { r = {"LADY MACBETH"}, t = "I’ll gild the faces of the grooms withal," },
    { r = {"LADY MACBETH"}, t = "For it must seem their guilt." },
    { d = "Exit. Knocking within" },
    { r = {"MACBETH"}, t = "Whence is that knocking?" },
    { r = {"MACBETH"}, t = "How is’t with me, when every noise appals me?" },
    { r = {"MACBETH"}, t = "What hands are here? Ha, they pluck out mine eyes!" },
    { r = {"MACBETH"}, t = "Will all great Neptune’s ocean wash this blood" },
    { r = {"MACBETH"}, t = "Clean from my hand? No, this my hand will rather" },
    { r = {"MACBETH"}, t = "The multitudinous seas incarnadine," },
    { r = {"MACBETH"}, t = "Making the green one red." },
    { d = "Enter Lady Macbeth" },
    { r = {"LADY MACBETH"}, t = "My hands are of your color, but I shame" },
    { r = {"LADY MACBETH"}, t = "To wear a heart so white." },
    { r = {"LADY MACBETH"}, t = "I hear knocking", d = "Knocking within" },
    { r = {"LADY MACBETH"}, t = "At the south entry:—retire we to our chamber." },
    { r = {"LADY MACBETH"}, t = "A little water clears us of this deed:" },
    { r = {"LADY MACBETH"}, t = "How easy is it then! Your constancy" },
    { r = {"LADY MACBETH"}, t = "Hath left you unattended." },
    { r = {"LADY MACBETH"}, t = "Hark, more knocking.", d = "Knocking within" },
    { r = {"LADY MACBETH"}, t = "Get on your nightgown, lest occasion call us" },
    { r = {"LADY MACBETH"}, t = "And show us to be watchers. Be not lost" },
    { r = {"LADY MACBETH"}, t = "So poorly in your thoughts." },
    { r = {"MACBETH"}, t = "To know my deed, ’twere best not know myself." },
    { r = {"MACBETH"}, t = "Wake Duncan with thy knocking! I would thou couldst!", d = "Knocking within" },
    { d = "Exeunt" },
    { d = "Act 2, Scene 3. The same.", h = true },
    { d = "Enter a Porter. Knocking within" },
    { r = {"PORTER"}, t = "Here’s a knocking indeed!" },
    { r = {"PORTER"}, t = "If a man were porter of hell gate, he should have old turning the key." },
    { r = {"PORTER"}, t = "Knock, knock, knock.", d = "Knocking" },
    { r = {"PORTER"}, t = "Who’s there, i’ th’ name of Belzebub?" },
    { r = {"PORTER"}, t = "Here’s a farmer that hanged himself on the expectation of plenty: come in time; have napkins enow about you; here you’ll sweat for’t." },
    { r = {"PORTER"}, t = "Knock, knock!", d = "Knocking" },
    { r = {"PORTER"}, t = "Who’s there, i’ th’ other devil’s name?" },
    { r = {"PORTER"}, t = "Faith, here’s an equivocator, that could swear in both the scales against either scale, who committed treason enough for God’s sake, yet could not equivocate to heaven: O, come in, equivocator." },
    { r = {"PORTER"}, t = "Knock, knock, knock!", d = "Knocking" },
    { r = {"PORTER"}, t = "Who’s there?" },
    { r = {"PORTER"}, t = "Faith, here’s an English tailor come hither, for stealing out of a French hose: come in, tailor; here you may roast your goose." },
    { r = {"PORTER"}, t = "Knock, knock.", d = "Knocking" },
    { r = {"PORTER"}, t = "Never at quiet!" },
    { r = {"PORTER"}, t = "What are you?—But this place is too cold for hell." },
    { r = {"PORTER"}, t = "I’ll devil-porter it no further: I had thought to have let in some of all professions, that go the primrose way to th’ everlasting bonfire." },
    { r = {"PORTER"}, t = "Anon, anon! I pray you, remember the porter.", d = "Knocking" },
    { d = "Opens the gate" },
    { d = "Enter Macduff and Lennox" },
    { r = {"MACDUFF"}, t = "Was it so late, friend, ere you went to bed," },
    { r = {"MACDUFF"}, t = "That you do lie so late?" },
    { r = {"PORTER"}, t = "Faith, sir, we were carousing till the second cock; and drink, sir, is a great provoker of three things." },
    { r = {"MACDUFF"}, t = "What three things does drink especially provoke?" },
    { r = {"PORTER"}, t = "Marry, sir, nose-painting, sleep, and urine." },
    { r = {"PORTER"}, t = "Lechery, sir, it provokes and unprovokes; it provokes the desire, but it takes away the performance." },
    { r = {"PORTER"}, t = "Therefore much drink may be said to be an equivocator with lechery: it makes him, and it mars him; it sets him on, and it takes him off; it persuades him, and disheartens him; makes him stand to, and not stand to;" },
    { r = {"PORTER"}, t = "in conclusion, equivocates him in a sleep, and giving him the lie, leaves him." },
    { r = {"MACDUFF"}, t = "I believe drink gave thee the lie last night." },
    { r = {"PORTER"}, t = "That it did, sir, i’ the very throat on me; but I requited him for his lie; and (I think) being too strong for him, though he took up my legs sometime, yet I made a shift to cast him." },
    { r = {"MACDUFF"}, t = "Is thy master stirring?" },
    { d = "Enter Macbeth" },
    { r = {"MACDUFF"}, t = "Our knocking has awak’d him; here he comes." },
    { r = {"LENNOX"}, t = "Good morrow, noble sir!" },
    { r = {"MACBETH"}, t = "Good morrow, both!" },
    { r = {"MACDUFF"}, t = "Is the King stirring, worthy thane?" },
    { r = {"MACBETH"}, t = "Not yet." },
    { r = {"MACDUFF"}, t = "He did command me to call timely on him." },
    { r = {"MACDUFF"}, t = "I have almost slipp’d the hour." },
    { r = {"MACBETH"}, t = "I’ll bring you to him." },
    { r = {"MACDUFF"}, t = "I know this is a joyful trouble to you;" },
    { r = {"MACDUFF"}, t = "But yet ’tis one." },
    { r = {"MACBETH"}, t = "The labour we delight in physics pain." },
    { r = {"MACBETH"}, t = "This is the door." },
    { r = {"MACDUFF"}, t = "I’ll make so bold to call." },
    { r = {"MACDUFF"}, t = "For ’tis my limited service." },
    { d = "Exit Macduff" },
    { r = {"LENNOX"}, t = "Goes the King hence today?" },
    { r = {"MACBETH"}, t = "He does. He did appoint so." },
    { r = {"LENNOX"}, t = "The night has been unruly: where we lay," },
    { r = {"LENNOX"}, t = "Our chimneys were blown down and, as they say," },
    { r = {"LENNOX"}, t = "Lamentings heard i’ th’ air, strange screams of death," },
    { r = {"LENNOX"}, t = "And prophesying, with accents terrible," },
    { r = {"LENNOX"}, t = "Of dire combustion and confus’d events," },
    { r = {"LENNOX"}, t = "New hatch’d to the woeful time. The obscure bird" },
    { r = {"LENNOX"}, t = "Clamour’d the live-long night. Some say the earth" },
    { r = {"LENNOX"}, t = "Was feverous, and did shake." },
    { r = {"MACBETH"}, t = "’Twas a rough night." },
    { r = {"LENNOX"}, t = "My young remembrance cannot parallel" },
    { r = {"LENNOX"}, t = "A fellow to it." },
    { d = "Enter Macduff" },
    { r = {"MACDUFF"}, t = "O horror, horror, horror!" },
    { r = {"MACDUFF"}, t = "Tongue nor heart cannot conceive nor name thee!" },
    { r = {"MACDUFF"}, t = "MACBETH, LENNOX." },
    { r = {"MACDUFF"}, t = "What’s the matter?" },
    { r = {"MACDUFF"}, t = "Confusion now hath made his masterpiece!" },
    { r = {"MACDUFF"}, t = "Most sacrilegious murder hath broke ope" },
    { r = {"MACDUFF"}, t = "The Lord’s anointed temple, and stole thence" },
    { r = {"MACDUFF"}, t = "The life o’ th’ building." },
    { r = {"MACBETH"}, t = "What is’t you say? the life?" },
    { r = {"LENNOX"}, t = "Mean you his majesty?" },
    { r = {"MACDUFF"}, t = "Approach the chamber, and destroy your sight" },
    { r = {"MACDUFF"}, t = "With a new Gorgon. Do not bid me speak." },
    { r = {"MACDUFF"}, t = "See, and then speak yourselves." },
    { d = "Exeunt Macbeth and Lennox" },
    { r = {"MACDUFF"}, t = "Awake, awake!—" },
    { r = {"MACDUFF"}, t = "Ring the alarum bell.—Murder and treason!" },
    { r = {"MACDUFF"}, t = "Banquo and Donalbain! Malcolm! awake!" },
    { r = {"MACDUFF"}, t = "Shake off this downy sleep, death’s counterfeit," },
    { r = {"MACDUFF"}, t = "And look on death itself! Up, up, and see" },
    { r = {"MACDUFF"}, t = "The great doom’s image. Malcolm! Banquo!" },
    { r = {"MACDUFF"}, t = "As from your graves rise up, and walk like sprites" },
    { r = {"MACDUFF"}, t = "To countenance this horror!" },
    { d = "Alarum-bell rings" },
    { d = "Enter Lady Macbeth" },
    { r = {"LADY MACBETH"}, t = "What’s the business," },
    { r = {"LADY MACBETH"}, t = "That such a hideous trumpet calls to parley" },
    { r = {"LADY MACBETH"}, t = "The sleepers of the house? Speak, speak!" },
    { r = {"MACDUFF"}, t = "O gentle lady," },
    { r = {"MACDUFF"}, t = "’Tis not for you to hear what I can speak:" },
    { r = {"MACDUFF"}, t = "The repetition, in a woman’s ear," },
    { r = {"MACDUFF"}, t = "Would murder as it fell." },
    { d = "Enter Banquo" },
    { r = {"MACDUFF"}, t = "O Banquo, Banquo!" },
    { r = {"MACDUFF"}, t = "Our royal master’s murder’d!" },
    { r = {"LADY MACBETH"}, t = "Woe, alas!" },
    { r = {"LADY MACBETH"}, t = "What, in our house?" },
    { r = {"BANQUO"}, t = "Too cruel anywhere.—" },
    { r = {"BANQUO"}, t = "Dear Duff, I pr’ythee, contradict thyself," },
    { r = {"BANQUO"}, t = "And say it is not so." },
    { d = "Enter Macbeth and Lennox with Ross" },
    { r = {"MACBETH"}, t = "Had I but died an hour before this chance," },
    { r = {"MACBETH"}, t = "I had liv’d a blessed time; for, from this instant" },
    { r = {"MACBETH"}, t = "There’s nothing serious in mortality." },
    { r = {"MACBETH"}, t = "All is but toys: renown and grace is dead;" },
    { r = {"MACBETH"}, t = "The wine of life is drawn, and the mere lees" },
    { r = {"MACBETH"}, t = "Is left this vault to brag of." },
    { d = "Enter Malcolm and Donalbain" },
    { r = {"DONALBAIN"}, t = "What is amiss?" },
    { r = {"MACBETH"}, t = "You are, and do not know’t:" },
    { r = {"MACBETH"}, t = "The spring, the head, the fountain of your blood" },
    { r = {"MACBETH"}, t = "Is stopp’d; the very source of it is stopp’d." },
    { r = {"MACDUFF"}, t = "Your royal father’s murder’d." },
    { r = {"MALCOLM"}, t = "O, by whom?" },
    { r = {"LENNOX"}, t = "Those of his chamber, as it seem’d, had done’t:" },
    { r = {"LENNOX"}, t = "Their hands and faces were all badg’d with blood;" },
    { r = {"LENNOX"}, t = "So were their daggers, which, unwip’d, we found" },
    { r = {"LENNOX"}, t = "Upon their pillows. They star’d, and were distracted;" },
    { r = {"LENNOX"}, t = "No man’s life was to be trusted with them." },
    { r = {"MACBETH"}, t = "O, yet I do repent me of my fury," },
    { r = {"MACBETH"}, t = "That I did kill them." },
    { r = {"MACDUFF"}, t = "Wherefore did you so?" },
    { r = {"MACBETH"}, t = "Who can be wise, amaz’d, temperate, and furious," },
    { r = {"MACBETH"}, t = "Loyal and neutral, in a moment? No man:" },
    { r = {"MACBETH"}, t = "Th’ expedition of my violent love" },
    { r = {"MACBETH"}, t = "Outrun the pauser, reason. Here lay Duncan," },
    { r = {"MACBETH"}, t = "His silver skin lac’d with his golden blood;" },
    { r = {"MACBETH"}, t = "And his gash’d stabs look’d like a breach in nature" },
    { r = {"MACBETH"}, t = "For ruin’s wasteful entrance: there, the murderers," },
    { r = {"MACBETH"}, t = "Steep’d in the colours of their trade, their daggers" },
    { r = {"MACBETH"}, t = "Unmannerly breech’d with gore. Who could refrain," },
    { r = {"MACBETH"}, t = "That had a heart to love, and in that heart" },
    { r = {"MACBETH"}, t = "Courage to make’s love known?" },
    { r = {"LADY MACBETH"}, t = "Help me hence, ho!" },
    { r = {"MACDUFF"}, t = "Look to the lady." },
    { r = {"MALCOLM"}, t = "Why do we hold our tongues," },
    { r = {"MALCOLM"}, t = "That most may claim this argument for ours?" },
    { r = {"DONALBAIN"}, t = "What should be spoken here, where our fate," },
    { r = {"DONALBAIN"}, t = "Hid in an auger hole, may rush, and seize us?" },
    { r = {"DONALBAIN"}, t = "Let’s away. Our tears are not yet brew’d." },
    { r = {"MALCOLM"}, t = "Nor our strong sorrow" },
    { r = {"MALCOLM"}, t = "Upon the foot of motion." },
    { r = {"BANQUO"}, t = "Look to the lady:" },
    { d = "Lady Macbeth is carried out" },
    { r = {"BANQUO"}, t = "And when we have our naked frailties hid," },
    { r = {"BANQUO"}, t = "That suffer in exposure, let us meet," },
    { r = {"BANQUO"}, t = "And question this most bloody piece of work" },
    { r = {"BANQUO"}, t = "To know it further. Fears and scruples shake us:" },
    { r = {"BANQUO"}, t = "In the great hand of God I stand; and thence" },
    { r = {"BANQUO"}, t = "Against the undivulg’d pretence I fight" },
    { r = {"BANQUO"}, t = "Of treasonous malice." },
    { r = {"MACDUFF"}, t = "And so do I." },
    { r = {"ALL"}, t = "So all." },
    { r = {"MACBETH"}, t = "Let’s briefly put on manly readiness," },
    { r = {"MACBETH"}, t = "And meet i’ th’ hall together." },
    { r = {"ALL"}, t = "Well contented." },
    { d = "Exeunt all but Malcolm and Donalbain" },
    { r = {"MALCOLM"}, t = "What will you do? Let’s not consort with them:" },
    { r = {"MALCOLM"}, t = "To show an unfelt sorrow is an office" },
    { r = {"MALCOLM"}, t = "Which the false man does easy. I’ll to England." },
    { r = {"DONALBAIN"}, t = "To Ireland, I. Our separated fortune" },
    { r = {"DONALBAIN"}, t = "Shall keep us both the safer. Where we are," },
    { r = {"DONALBAIN"}, t = "There’s daggers in men’s smiles: the near in blood," },
    { r = {"DONALBAIN"}, t = "The nearer bloody." },
    { r = {"MALCOLM"}, t = "This murderous shaft that’s shot" },
    { r = {"MALCOLM"}, t = "Hath not yet lighted; and our safest way" },
    { r = {"MALCOLM"}, t = "Is to avoid the aim. Therefore to horse;" },
    { r = {"MALCOLM"}, t = "And let us not be dainty of leave-taking," },
    { r = {"MALCOLM"}, t = "But shift away. There’s warrant in that theft" },
    { r = {"MALCOLM"}, t = "Which steals itself, when there’s no mercy left." },
    { d = "Exeunt" },
    { d = "Act 2, Scene 4. The same. Without the Castle.", h = true },
    { d = "Enter Ross and an Old Man" },
    { r = {"OLD MAN"}, t = "Threescore and ten I can remember well," },
    { r = {"OLD MAN"}, t = "Within the volume of which time I have seen" },
    { r = {"OLD MAN"}, t = "Hours dreadful and things strange, but this sore night" },
    { r = {"OLD MAN"}, t = "Hath trifled former knowings." },
    { r = {"ROSS"}, t = "Ha, good father," },
    { r = {"ROSS"}, t = "Thou seest the heavens, as troubled with man’s act," },
    { r = {"ROSS"}, t = "Threatens his bloody stage: by the clock ’tis day," },
    { r = {"ROSS"}, t = "And yet dark night strangles the travelling lamp." },
    { r = {"ROSS"}, t = "Is’t night’s predominance, or the day’s shame," },
    { r = {"ROSS"}, t = "That darkness does the face of earth entomb," },
    { r = {"ROSS"}, t = "When living light should kiss it?" },
    { r = {"OLD MAN"}, t = "’Tis unnatural," },
    { r = {"OLD MAN"}, t = "Even like the deed that’s done. On Tuesday last," },
    { r = {"OLD MAN"}, t = "A falcon, towering in her pride of place," },
    { r = {"OLD MAN"}, t = "Was by a mousing owl hawk’d at and kill’d." },
    { r = {"ROSS"}, t = "And Duncan’s horses (a thing most strange and certain)" },
    { r = {"ROSS"}, t = "Beauteous and swift, the minions of their race," },
    { r = {"ROSS"}, t = "Turn’d wild in nature, broke their stalls, flung out," },
    { r = {"ROSS"}, t = "Contending ’gainst obedience, as they would make" },
    { r = {"ROSS"}, t = "War with mankind." },
    { r = {"OLD MAN"}, t = "’Tis said they eat each other." },
    { r = {"ROSS"}, t = "They did so; to the amazement of mine eyes," },
    { r = {"ROSS"}, t = "That look’d upon’t." },
    { r = {"ROSS"}, t = "Here comes the good Macduff." },
    { d = "Enter Macduff" },
    { r = {"ROSS"}, t = "How goes the world, sir, now?" },
    { r = {"MACDUFF"}, t = "Why, see you not?" },
    { r = {"ROSS"}, t = "Is’t known who did this more than bloody deed?" },
    { r = {"MACDUFF"}, t = "Those that Macbeth hath slain." },
    { r = {"ROSS"}, t = "Alas, the day!" },
    { r = {"ROSS"}, t = "What good could they pretend?" },
    { r = {"MACDUFF"}, t = "They were suborn’d." },
    { r = {"MACDUFF"}, t = "Malcolm and Donalbain, the King’s two sons," },
    { r = {"MACDUFF"}, t = "Are stol’n away and fled; which puts upon them" },
    { r = {"MACDUFF"}, t = "Suspicion of the deed." },
    { r = {"ROSS"}, t = "’Gainst nature still:" },
    { r = {"ROSS"}, t = "Thriftless ambition, that will ravin up" },
    { r = {"ROSS"}, t = "Thine own life’s means!—Then ’tis most like" },
    { r = {"ROSS"}, t = "The sovereignty will fall upon Macbeth." },
    { r = {"MACDUFF"}, t = "He is already nam’d; and gone to Scone" },
    { r = {"MACDUFF"}, t = "To be invested." },
    { r = {"ROSS"}, t = "Where is Duncan’s body?" },
    { r = {"MACDUFF"}, t = "Carried to Colmekill," },
    { r = {"MACDUFF"}, t = "The sacred storehouse of his predecessors," },
    { r = {"MACDUFF"}, t = "And guardian of their bones." },
    { r = {"ROSS"}, t = "Will you to Scone?" },
    { r = {"MACDUFF"}, t = "No, cousin, I’ll to Fife." },
    { r = {"ROSS"}, t = "Well, I will thither." },
    { r = {"MACDUFF"}, t = "Well, may you see things well done there. Adieu!" },
    { r = {"MACDUFF"}, t = "Lest our old robes sit easier than our new!" },
    { r = {"ROSS"}, t = "Farewell, father." },
    { r = {"OLD MAN"}, t = "God’s benison go with you; and with those" },
    { r = {"OLD MAN"}, t = "That would make good of bad, and friends of foes!" },
    { d = "Exeunt" },
    { d = "Act 3, Scene 1. Forres. A Room in the Palace.", h = true },
    { d = "Enter Banquo" },
    { r = {"BANQUO"}, t = "Thou hast it now, King, Cawdor, Glamis, all," },
    { r = {"BANQUO"}, t = "As the Weird Women promis’d; and, I fear," },
    { r = {"BANQUO"}, t = "Thou play’dst most foully for’t; yet it was said" },
    { r = {"BANQUO"}, t = "It should not stand in thy posterity;" },
    { r = {"BANQUO"}, t = "But that myself should be the root and father" },
    { r = {"BANQUO"}, t = "Of many kings. If there come truth from them" },
    { r = {"BANQUO"}, t = "(As upon thee, Macbeth, their speeches shine)" },
    { r = {"BANQUO"}, t = "Why, by the verities on thee made good," },
    { r = {"BANQUO"}, t = "May they not be my oracles as well," },
    { r = {"BANQUO"}, t = "And set me up in hope? But hush; no more." },
    { d = "Sennet sounded. Enter Macbeth as King, Lady Macbeth as Queen; Lennox, Ross, Lords, and Attendants" },
    { r = {"MACBETH"}, t = "Here’s our chief guest." },
    { r = {"LADY MACBETH"}, t = "If he had been forgotten," },
    { r = {"LADY MACBETH"}, t = "It had been as a gap in our great feast," },
    { r = {"LADY MACBETH"}, t = "And all-thing unbecoming." },
    { r = {"MACBETH"}, t = "Tonight we hold a solemn supper, sir," },
    { r = {"MACBETH"}, t = "And I’ll request your presence." },
    { r = {"BANQUO"}, t = "Let your Highness" },
    { r = {"BANQUO"}, t = "Command upon me, to the which my duties" },
    { r = {"BANQUO"}, t = "Are with a most indissoluble tie" },
    { r = {"BANQUO"}, t = "For ever knit." },
    { r = {"MACBETH"}, t = "Ride you this afternoon?" },
    { r = {"BANQUO"}, t = "Ay, my good lord." },
    { r = {"MACBETH"}, t = "We should have else desir’d your good advice" },
    { r = {"MACBETH"}, t = "(Which still hath been both grave and prosperous)" },
    { r = {"MACBETH"}, t = "In this day’s council; but we’ll take tomorrow." },
    { r = {"MACBETH"}, t = "Is’t far you ride?" },
    { r = {"BANQUO"}, t = "As far, my lord, as will fill up the time" },
    { r = {"BANQUO"}, t = "’Twixt this and supper: go not my horse the better," },
    { r = {"BANQUO"}, t = "I must become a borrower of the night," },
    { r = {"BANQUO"}, t = "For a dark hour or twain." },
    { r = {"MACBETH"}, t = "Fail not our feast." },
    { r = {"BANQUO"}, t = "My lord, I will not." },
    { r = {"MACBETH"}, t = "We hear our bloody cousins are bestow’d" },
    { r = {"MACBETH"}, t = "In England and in Ireland; not confessing" },
    { r = {"MACBETH"}, t = "Their cruel parricide, filling their hearers" },
    { r = {"MACBETH"}, t = "With strange invention. But of that tomorrow," },
    { r = {"MACBETH"}, t = "When therewithal we shall have cause of state" },
    { r = {"MACBETH"}, t = "Craving us jointly. Hie you to horse: adieu," },
    { r = {"MACBETH"}, t = "Till you return at night. Goes Fleance with you?" },
    { r = {"BANQUO"}, t = "Ay, my good lord: our time does call upon’s." },
    { r = {"MACBETH"}, t = "I wish your horses swift and sure of foot;" },
    { r = {"MACBETH"}, t = "And so I do commend you to their backs." },
    { r = {"MACBETH"}, t = "Farewell." },
    { d = "Exit Banquo" },
    { r = {"MACBETH"}, t = "Let every man be master of his time" },
    { r = {"MACBETH"}, t = "Till seven at night; to make society" },
    { r = {"MACBETH"}, t = "The sweeter welcome, we will keep ourself" },
    { r = {"MACBETH"}, t = "Till supper time alone: while then, God be with you." },
    { d = "Exeunt Lady Macbeth, Lords, &c" },
    { r = {"MACBETH"}, t = "Sirrah, a word with you. Attend those men" },
    { r = {"MACBETH"}, t = "Our pleasure?" },
    { r = {"SERVANT"}, t = "They are, my lord, without the palace gate." },
    { r = {"MACBETH"}, t = "Bring them before us." },
    { d = "Exit Servant" },
    { r = {"MACBETH"}, t = "To be thus is nothing," },
    { r = {"MACBETH"}, t = "But to be safely thus. Our fears in Banquo" },
    { r = {"MACBETH"}, t = "Stick deep, and in his royalty of nature" },
    { r = {"MACBETH"}, t = "Reigns that which would be fear’d: ’tis much he dares;" },
    { r = {"MACBETH"}, t = "And, to that dauntless temper of his mind," },
    { r = {"MACBETH"}, t = "He hath a wisdom that doth guide his valour" },
    { r = {"MACBETH"}, t = "To act in safety. There is none but he" },
    { r = {"MACBETH"}, t = "Whose being I do fear: and under him" },
    { r = {"MACBETH"}, t = "My genius is rebuk’d; as, it is said," },
    { r = {"MACBETH"}, t = "Mark Antony’s was by Caesar. He chid the sisters" },
    { r = {"MACBETH"}, t = "When first they put the name of king upon me," },
    { r = {"MACBETH"}, t = "And bade them speak to him; then, prophet-like," },
    { r = {"MACBETH"}, t = "They hail’d him father to a line of kings:" },
    { r = {"MACBETH"}, t = "Upon my head they plac’d a fruitless crown," },
    { r = {"MACBETH"}, t = "And put a barren sceptre in my gripe," },
    { r = {"MACBETH"}, t = "Thence to be wrench’d with an unlineal hand," },
    { r = {"MACBETH"}, t = "No son of mine succeeding. If’t be so," },
    { r = {"MACBETH"}, t = "For Banquo’s issue have I fil’d my mind;" },
    { r = {"MACBETH"}, t = "For them the gracious Duncan have I murder’d;" },
    { r = {"MACBETH"}, t = "Put rancours in the vessel of my peace" },
    { r = {"MACBETH"}, t = "Only for them; and mine eternal jewel" },
    { r = {"MACBETH"}, t = "Given to the common enemy of man," },
    { r = {"MACBETH"}, t = "To make them kings, the seed of Banquo kings!" },
    { r = {"MACBETH"}, t = "Rather than so, come, fate, into the list," },
    { r = {"MACBETH"}, t = "And champion me to th’ utterance!—Who’s there?" },
    { d = "Enter Servant with two Murderers" },
    { r = {"MACBETH"}, t = "Now go to the door, and stay there till we call." },
    { d = "Exit Servant" },
    { r = {"MACBETH"}, t = "Was it not yesterday we spoke together?" },
    { r = {"FIRST MURDERER"}, t = "It was, so please your Highness." },
    { r = {"MACBETH"}, t = "Well then, now" },
    { r = {"MACBETH"}, t = "Have you consider’d of my speeches? Know" },
    { r = {"MACBETH"}, t = "That it was he, in the times past, which held you" },
    { r = {"MACBETH"}, t = "So under fortune, which you thought had been" },
    { r = {"MACBETH"}, t = "Our innocent self? This I made good to you" },
    { r = {"MACBETH"}, t = "In our last conference, pass’d in probation with you" },
    { r = {"MACBETH"}, t = "How you were borne in hand, how cross’d, the instruments," },
    { r = {"MACBETH"}, t = "Who wrought with them, and all things else that might" },
    { r = {"MACBETH"}, t = "To half a soul and to a notion craz’d" },
    { r = {"MACBETH"}, t = "Say, “Thus did Banquo.”" },
    { r = {"FIRST MURDERER"}, t = "You made it known to us." },
    { r = {"MACBETH"}, t = "I did so; and went further, which is now" },
    { r = {"MACBETH"}, t = "Our point of second meeting. Do you find" },
    { r = {"MACBETH"}, t = "Your patience so predominant in your nature," },
    { r = {"MACBETH"}, t = "That you can let this go? Are you so gospell’d," },
    { r = {"MACBETH"}, t = "To pray for this good man and for his issue," },
    { r = {"MACBETH"}, t = "Whose heavy hand hath bow’d you to the grave," },
    { r = {"MACBETH"}, t = "And beggar’d yours forever?" },
    { r = {"FIRST MURDERER"}, t = "We are men, my liege." },
    { r = {"MACBETH"}, t = "Ay, in the catalogue ye go for men;" },
    { r = {"MACBETH"}, t = "As hounds, and greyhounds, mongrels, spaniels, curs," },
    { r = {"MACBETH"}, t = "Shoughs, water-rugs, and demi-wolves are clept" },
    { r = {"MACBETH"}, t = "All by the name of dogs: the valu’d file" },
    { r = {"MACBETH"}, t = "Distinguishes the swift, the slow, the subtle," },
    { r = {"MACBETH"}, t = "The housekeeper, the hunter, every one" },
    { r = {"MACBETH"}, t = "According to the gift which bounteous nature" },
    { r = {"MACBETH"}, t = "Hath in him clos’d; whereby he does receive" },
    { r = {"MACBETH"}, t = "Particular addition, from the bill" },
    { r = {"MACBETH"}, t = "That writes them all alike: and so of men." },
    { r = {"MACBETH"}, t = "Now, if you have a station in the file," },
    { r = {"MACBETH"}, t = "Not i’ th’ worst rank of manhood, say’t;" },
    { r = {"MACBETH"}, t = "And I will put that business in your bosoms," },
    { r = {"MACBETH"}, t = "Whose execution takes your enemy off," },
    { r = {"MACBETH"}, t = "Grapples you to the heart and love of us," },
    { r = {"MACBETH"}, t = "Who wear our health but sickly in his life," },
    { r = {"MACBETH"}, t = "Which in his death were perfect." },
    { r = {"SECOND MURDERER"}, t = "I am one, my liege," },
    { r = {"SECOND MURDERER"}, t = "Whom the vile blows and buffets of the world" },
    { r = {"SECOND MURDERER"}, t = "Hath so incens’d that I am reckless what" },
    { r = {"SECOND MURDERER"}, t = "I do to spite the world." },
    { r = {"FIRST MURDERER"}, t = "And I another," },
    { r = {"FIRST MURDERER"}, t = "So weary with disasters, tugg’d with fortune," },
    { r = {"FIRST MURDERER"}, t = "That I would set my life on any chance," },
    { r = {"FIRST MURDERER"}, t = "To mend it or be rid on’t." },
    { r = {"MACBETH"}, t = "Both of you" },
    { r = {"MACBETH"}, t = "Know Banquo was your enemy." },
    { r = {"FIRST MURDERER", "SECOND MURDERER"}, t = "True, my lord." },
    { r = {"MACBETH"}, t = "So is he mine; and in such bloody distance," },
    { r = {"MACBETH"}, t = "That every minute of his being thrusts" },
    { r = {"MACBETH"}, t = "Against my near’st of life; and though I could" },
    { r = {"MACBETH"}, t = "With barefac’d power sweep him from my sight," },
    { r = {"MACBETH"}, t = "And bid my will avouch it, yet I must not," },
    { r = {"MACBETH"}, t = "For certain friends that are both his and mine," },
    { r = {"MACBETH"}, t = "Whose loves I may not drop, but wail his fall" },
    { r = {"MACBETH"}, t = "Who I myself struck down: and thence it is" },
    { r = {"MACBETH"}, t = "That I to your assistance do make love," },
    { r = {"MACBETH"}, t = "Masking the business from the common eye" },
    { r = {"MACBETH"}, t = "For sundry weighty reasons." },
    { r = {"SECOND MURDERER"}, t = "We shall, my lord," },
    { r = {"SECOND MURDERER"}, t = "Perform what you command us." },
    { r = {"FIRST MURDERER"}, t = "Though our lives" },
    { r = {"MACBETH"}, t = "Your spirits shine through you. Within this hour at most," },
    { r = {"MACBETH"}, t = "I will advise you where to plant yourselves," },
    { r = {"MACBETH"}, t = "Acquaint you with the perfect spy o’ th’ time," },
    { r = {"MACBETH"}, t = "The moment on’t; for’t must be done tonight" },
    { r = {"MACBETH"}, t = "And something from the palace; always thought" },
    { r = {"MACBETH"}, t = "That I require a clearness. And with him" },
    { r = {"MACBETH"}, t = "(To leave no rubs nor botches in the work)" },
    { r = {"MACBETH"}, t = "Fleance his son, that keeps him company," },
    { r = {"MACBETH"}, t = "Whose absence is no less material to me" },
    { r = {"MACBETH"}, t = "Than is his father’s, must embrace the fate" },
    { r = {"MACBETH"}, t = "Of that dark hour. Resolve yourselves apart." },
    { r = {"MACBETH"}, t = "I’ll come to you anon." },
    { r = {"FIRST MURDERER", "SECOND MURDERER"}, t = "We are resolv’d, my lord." },
    { r = {"MACBETH"}, t = "I’ll call upon you straight: abide within." },
    { d = "Exeunt Murderers" },
    { r = {"MACBETH"}, t = "It is concluded. Banquo, thy soul’s flight," },
    { r = {"MACBETH"}, t = "If it find heaven, must find it out tonight." },
    { d = "Exit" },
    { d = "Act 3, Scene 2. The same. Another Room in the Palace.", h = true },
    { d = "Enter Lady Macbeth and a Servant" },
    { r = {"LADY MACBETH"}, t = "Is Banquo gone from court?" },
    { r = {"SERVANT"}, t = "Ay, madam, but returns again tonight." },
    { r = {"LADY MACBETH"}, t = "Say to the King, I would attend his leisure" },
    { r = {"LADY MACBETH"}, t = "For a few words." },
    { r = {"SERVANT"}, t = "Madam, I will." },
    { d = "Exit" },
    { r = {"LADY MACBETH"}, t = "Naught’s had, all’s spent," },
    { r = {"LADY MACBETH"}, t = "Where our desire is got without content:" },
    { r = {"LADY MACBETH"}, t = "’Tis safer to be that which we destroy," },
    { r = {"LADY MACBETH"}, t = "Than by destruction dwell in doubtful joy." },
    { d = "Enter Macbeth" },
    { r = {"LADY MACBETH"}, t = "How now, my lord, why do you keep alone," },
    { r = {"LADY MACBETH"}, t = "Of sorriest fancies your companions making," },
    { r = {"LADY MACBETH"}, t = "Using those thoughts which should indeed have died" },
    { r = {"LADY MACBETH"}, t = "With them they think on? Things without all remedy" },
    { r = {"LADY MACBETH"}, t = "Should be without regard: what’s done is done." },
    { r = {"MACBETH"}, t = "We have scorch’d the snake, not kill’d it." },
    { r = {"MACBETH"}, t = "She’ll close, and be herself; whilst our poor malice" },
    { r = {"MACBETH"}, t = "Remains in danger of her former tooth." },
    { r = {"MACBETH"}, t = "But let the frame of things disjoint," },
    { r = {"MACBETH"}, t = "Both the worlds suffer," },
    { r = {"MACBETH"}, t = "Ere we will eat our meal in fear, and sleep" },
    { r = {"MACBETH"}, t = "In the affliction of these terrible dreams" },
    { r = {"MACBETH"}, t = "That shake us nightly. Better be with the dead," },
    { r = {"MACBETH"}, t = "Whom we, to gain our peace, have sent to peace," },
    { r = {"MACBETH"}, t = "Than on the torture of the mind to lie" },
    { r = {"MACBETH"}, t = "In restless ecstasy. Duncan is in his grave;" },
    { r = {"MACBETH"}, t = "After life’s fitful fever he sleeps well;" },
    { r = {"MACBETH"}, t = "Treason has done his worst: nor steel, nor poison," },
    { r = {"MACBETH"}, t = "Malice domestic, foreign levy, nothing" },
    { r = {"MACBETH"}, t = "Can touch him further." },
    { r = {"LADY MACBETH"}, t = "Come on," },
    { r = {"LADY MACBETH"}, t = "Gently my lord, sleek o’er your rugged looks;" },
    { r = {"LADY MACBETH"}, t = "Be bright and jovial among your guests tonight." },
    { r = {"MACBETH"}, t = "So shall I, love; and so, I pray, be you." },
    { r = {"MACBETH"}, t = "Let your remembrance apply to Banquo;" },
    { r = {"MACBETH"}, t = "Present him eminence, both with eye and tongue:" },
    { r = {"MACBETH"}, t = "Unsafe the while, that we" },
    { r = {"MACBETH"}, t = "Must lave our honours in these flattering streams," },
    { r = {"MACBETH"}, t = "And make our faces vizards to our hearts," },
    { r = {"MACBETH"}, t = "Disguising what they are." },
    { r = {"LADY MACBETH"}, t = "You must leave this." },
    { r = {"MACBETH"}, t = "O, full of scorpions is my mind, dear wife!" },
    { r = {"MACBETH"}, t = "Thou know’st that Banquo, and his Fleance, lives." },
    { r = {"LADY MACBETH"}, t = "But in them nature’s copy’s not eterne." },
    { r = {"MACBETH"}, t = "There’s comfort yet; they are assailable." },
    { r = {"MACBETH"}, t = "Then be thou jocund. Ere the bat hath flown" },
    { r = {"MACBETH"}, t = "His cloister’d flight, ere to black Hecate’s summons" },
    { r = {"MACBETH"}, t = "The shard-born beetle, with his drowsy hums," },
    { r = {"MACBETH"}, t = "Hath rung night’s yawning peal, there shall be done" },
    { r = {"MACBETH"}, t = "A deed of dreadful note." },
    { r = {"LADY MACBETH"}, t = "What’s to be done?" },
    { r = {"MACBETH"}, t = "Be innocent of the knowledge, dearest chuck," },
    { r = {"MACBETH"}, t = "Till thou applaud the deed. Come, seeling night," },
    { r = {"MACBETH"}, t = "Scarf up the tender eye of pitiful day," },
    { r = {"MACBETH"}, t = "And with thy bloody and invisible hand" },
    { r = {"MACBETH"}, t = "Cancel and tear to pieces that great bond" },
    { r = {"MACBETH"}, t = "Which keeps me pale!—Light thickens; and the crow" },
    { r = {"MACBETH"}, t = "Makes wing to th’ rooky wood." },
    { r = {"MACBETH"}, t = "Good things of day begin to droop and drowse," },
    { r = {"MACBETH"}, t = "Whiles night’s black agents to their preys do rouse." },
    { r = {"MACBETH"}, t = "Thou marvell’st at my words: but hold thee still;" },
    { r = {"MACBETH"}, t = "Things bad begun make strong themselves by ill." },
    { r = {"MACBETH"}, t = "So, pr’ythee, go with me." },
    { d = "Exeunt" },
    { d = "Act 3, Scene 3. The same. A Park or Lawn, with a gate leading to the Palace.", h = true },
    { d = "Enter three Murderers" },
    { r = {"FIRST MURDERER"}, t = "But who did bid thee join with us?" },
    { r = {"THIRD MURDERER"}, t = "Macbeth." },
    { r = {"SECOND MURDERER"}, t = "He needs not our mistrust; since he delivers" },
    { r = {"SECOND MURDERER"}, t = "Our offices and what we have to do" },
    { r = {"SECOND MURDERER"}, t = "To the direction just." },
    { r = {"FIRST MURDERER"}, t = "Then stand with us." },
    { r = {"FIRST MURDERER"}, t = "The west yet glimmers with some streaks of day." },
    { r = {"FIRST MURDERER"}, t = "Now spurs the lated traveller apace," },
    { r = {"FIRST MURDERER"}, t = "To gain the timely inn; and near approaches" },
    { r = {"FIRST MURDERER"}, t = "The subject of our watch." },
    { r = {"THIRD MURDERER"}, t = "Hark! I hear horses." },
    { r = {"BANQUO"}, t = "Give us a light there, ho!", d = "Within" },
    { r = {"SECOND MURDERER"}, t = "Then ’tis he; the rest" },
    { r = {"SECOND MURDERER"}, t = "That are within the note of expectation" },
    { r = {"SECOND MURDERER"}, t = "Already are i’ th’ court." },
    { r = {"FIRST MURDERER"}, t = "His horses go about." },
    { r = {"THIRD MURDERER"}, t = "Almost a mile; but he does usually," },
    { r = {"THIRD MURDERER"}, t = "So all men do, from hence to the palace gate" },
    { r = {"THIRD MURDERER"}, t = "Make it their walk." },
    { d = "Enter Banquo and Fleance with a torch" },
    { r = {"SECOND MURDERER"}, t = "A light, a light!" },
    { r = {"THIRD MURDERER"}, t = "’Tis he." },
    { r = {"FIRST MURDERER"}, t = "Stand to’t." },
    { r = {"BANQUO"}, t = "It will be rain tonight." },
    { r = {"FIRST MURDERER"}, t = "Let it come down." },
    { d = "Assaults Banquo" },
    { r = {"BANQUO"}, t = "O, treachery! Fly, good Fleance, fly, fly, fly!" },
    { r = {"BANQUO"}, t = "Thou mayst revenge—O slave!" },
    { r = {"BANQUO"}, d = "Dies. Fleance escapes", e = "/lie", s = {"Feign Death"} },
    { r = {"THIRD MURDERER"}, t = "Who did strike out the light?" },
    { r = {"FIRST MURDERER"}, t = "Was’t not the way?" },
    { r = {"THIRD MURDERER"}, t = "There’s but one down: the son is fled." },
    { r = {"SECOND MURDERER"}, t = "We have lost best half of our affair." },
    { r = {"FIRST MURDERER"}, t = "Well, let’s away, and say how much is done." },
    { d = "Exeunt" },
    { d = "Act 3, Scene 4. The same. A Room of state in the Palace.", h = true },
    { d = "A banquet prepared. Enter Macbeth, Lady Macbeth, Ross, Lennox, Lords and Attendants" },
    { r = {"MACBETH"}, t = "You know your own degrees, sit down. At first" },
    { r = {"MACBETH"}, t = "And last the hearty welcome." },
    { r = {"LORDS"}, t = "Thanks to your Majesty." },
    { r = {"MACBETH"}, t = "Ourself will mingle with society," },
    { r = {"MACBETH"}, t = "And play the humble host." },
    { r = {"MACBETH"}, t = "Our hostess keeps her state; but, in best time," },
    { r = {"MACBETH"}, t = "We will require her welcome." },
    { r = {"LADY MACBETH"}, t = "Pronounce it for me, sir, to all our friends;" },
    { r = {"LADY MACBETH"}, t = "For my heart speaks they are welcome." },
    { d = "Enter first Murderer to the door" },
    { r = {"MACBETH"}, t = "See, they encounter thee with their hearts’ thanks." },
    { r = {"MACBETH"}, t = "Both sides are even: here I’ll sit i’ th’ midst." },
    { r = {"MACBETH"}, t = "Be large in mirth; anon we’ll drink a measure" },
    { r = {"MACBETH"}, t = "The table round. There’s blood upon thy face." },
    { r = {"MURDERER"}, t = "’Tis Banquo’s then." },
    { r = {"MACBETH"}, t = "’Tis better thee without than he within." },
    { r = {"MACBETH"}, t = "Is he dispatch’d?" },
    { r = {"MURDERER"}, t = "My lord, his throat is cut. That I did for him." },
    { r = {"MACBETH"}, t = "Thou art the best o’ th’ cut-throats;" },
    { r = {"MACBETH"}, t = "Yet he’s good that did the like for Fleance:" },
    { r = {"MACBETH"}, t = "If thou didst it, thou art the nonpareil." },
    { r = {"MURDERER"}, t = "Most royal sir," },
    { r = {"MURDERER"}, t = "Fleance is ’scap’d." },
    { r = {"MACBETH"}, t = "Then comes my fit again: I had else been perfect;" },
    { r = {"MACBETH"}, t = "Whole as the marble, founded as the rock," },
    { r = {"MACBETH"}, t = "As broad and general as the casing air:" },
    { r = {"MACBETH"}, t = "But now I am cabin’d, cribb’d, confin’d, bound in" },
    { r = {"MACBETH"}, t = "To saucy doubts and fears. But Banquo’s safe?" },
    { r = {"MURDERER"}, t = "Ay, my good lord. Safe in a ditch he bides," },
    { r = {"MURDERER"}, t = "With twenty trenched gashes on his head;" },
    { r = {"MURDERER"}, t = "The least a death to nature." },
    { r = {"MACBETH"}, t = "Thanks for that." },
    { r = {"MACBETH"}, t = "There the grown serpent lies; the worm that’s fled" },
    { r = {"MACBETH"}, t = "Hath nature that in time will venom breed," },
    { r = {"MACBETH"}, t = "No teeth for th’ present.—Get thee gone; tomorrow" },
    { r = {"MACBETH"}, t = "We’ll hear, ourselves, again." },
    { d = "Exit Murderer" },
    { r = {"LADY MACBETH"}, t = "My royal lord," },
    { r = {"LADY MACBETH"}, t = "You do not give the cheer: the feast is sold" },
    { r = {"LADY MACBETH"}, t = "That is not often vouch’d, while ’tis a-making," },
    { r = {"LADY MACBETH"}, t = "’Tis given with welcome. To feed were best at home;" },
    { r = {"LADY MACBETH"}, t = "From thence the sauce to meat is ceremony;" },
    { r = {"LADY MACBETH"}, t = "Meeting were bare without it." },
    { r = {"BANQUO"}, d = "The Ghost of Banquo rises, and sits in Macbeth’s place", s = {"Fade"} },
    { r = {"MACBETH"}, t = "Sweet remembrancer!—" },
    { r = {"MACBETH"}, t = "Now, good digestion wait on appetite," },
    { r = {"MACBETH"}, t = "And health on both!" },
    { r = {"LENNOX"}, t = "May’t please your Highness sit." },
    { r = {"MACBETH"}, t = "Here had we now our country’s honour roof’d," },
    { r = {"MACBETH"}, t = "Were the grac’d person of our Banquo present;" },
    { r = {"MACBETH"}, t = "Who may I rather challenge for unkindness" },
    { r = {"MACBETH"}, t = "Than pity for mischance!" },
    { r = {"ROSS"}, t = "His absence, sir," },
    { r = {"ROSS"}, t = "Lays blame upon his promise. Please’t your Highness" },
    { r = {"ROSS"}, t = "To grace us with your royal company?" },
    { r = {"MACBETH"}, t = "The table’s full." },
    { r = {"LENNOX"}, t = "Here is a place reserv’d, sir." },
    { r = {"MACBETH"}, t = "Where?" },
    { r = {"LENNOX"}, t = "Here, my good lord. What is’t that moves your Highness?" },
    { r = {"MACBETH"}, t = "Which of you have done this?" },
    { r = {"LORDS"}, t = "What, my good lord?" },
    { r = {"MACBETH"}, t = "Thou canst not say I did it. Never shake" },
    { r = {"MACBETH"}, t = "Thy gory locks at me." },
    { r = {"ROSS"}, t = "Gentlemen, rise; his Highness is not well." },
    { r = {"LADY MACBETH"}, t = "Sit, worthy friends. My lord is often thus," },
    { r = {"LADY MACBETH"}, t = "And hath been from his youth: pray you, keep seat;" },
    { r = {"LADY MACBETH"}, t = "The fit is momentary; upon a thought" },
    { r = {"LADY MACBETH"}, t = "He will again be well. If much you note him," },
    { r = {"LADY MACBETH"}, t = "You shall offend him, and extend his passion." },
    { r = {"LADY MACBETH"}, t = "Feed, and regard him not.—Are you a man?" },
    { r = {"MACBETH"}, t = "Ay, and a bold one, that dare look on that" },
    { r = {"MACBETH"}, t = "Which might appal the devil." },
    { r = {"LADY MACBETH"}, t = "O proper stuff!" },
    { r = {"LADY MACBETH"}, t = "This is the very painting of your fear:" },
    { r = {"LADY MACBETH"}, t = "This is the air-drawn dagger which you said," },
    { r = {"LADY MACBETH"}, t = "Led you to Duncan. O, these flaws, and starts" },
    { r = {"LADY MACBETH"}, t = "(Impostors to true fear), would well become" },
    { r = {"LADY MACBETH"}, t = "A woman’s story at a winter’s fire," },
    { r = {"LADY MACBETH"}, t = "Authoris’d by her grandam. Shame itself!" },
    { r = {"LADY MACBETH"}, t = "Why do you make such faces? When all’s done," },
    { r = {"LADY MACBETH"}, t = "You look but on a stool." },
    { r = {"MACBETH"}, t = "Pr’ythee, see there!" },
    { r = {"MACBETH"}, t = "Behold! look! lo! how say you?" },
    { r = {"MACBETH"}, t = "Why, what care I? If thou canst nod, speak too.—" },
    { r = {"MACBETH"}, t = "If charnel houses and our graves must send" },
    { r = {"MACBETH"}, t = "Those that we bury back, our monuments" },
    { r = {"MACBETH"}, t = "Shall be the maws of kites." },
    { r = {"BANQUO"}, d = "Ghost disappears", s = {"Invisibility", "Stealth", "Shadowmeld"} },
    { r = {"LADY MACBETH"}, t = "What, quite unmann’d in folly?" },
    { r = {"MACBETH"}, t = "If I stand here, I saw him." },
    { r = {"LADY MACBETH"}, t = "Fie, for shame!" },
    { r = {"MACBETH"}, t = "Blood hath been shed ere now, i’ th’ olden time," },
    { r = {"MACBETH"}, t = "Ere humane statute purg’d the gentle weal;" },
    { r = {"MACBETH"}, t = "Ay, and since too, murders have been perform’d" },
    { r = {"MACBETH"}, t = "Too terrible for the ear: the time has been," },
    { r = {"MACBETH"}, t = "That, when the brains were out, the man would die," },
    { r = {"MACBETH"}, t = "And there an end; but now they rise again," },
    { r = {"MACBETH"}, t = "With twenty mortal murders on their crowns," },
    { r = {"MACBETH"}, t = "And push us from our stools. This is more strange" },
    { r = {"MACBETH"}, t = "Than such a murder is." },
    { r = {"LADY MACBETH"}, t = "My worthy lord," },
    { r = {"LADY MACBETH"}, t = "Your noble friends do lack you." },
    { r = {"MACBETH"}, t = "I do forget.—" },
    { r = {"MACBETH"}, t = "Do not muse at me, my most worthy friends." },
    { r = {"MACBETH"}, t = "I have a strange infirmity, which is nothing" },
    { r = {"MACBETH"}, t = "To those that know me. Come, love and health to all;" },
    { r = {"MACBETH"}, t = "Then I’ll sit down.—Give me some wine, fill full.—" },
    { r = {"MACBETH"}, t = "I drink to the general joy o’ th’ whole table," },
    { r = {"MACBETH"}, t = "And to our dear friend Banquo, whom we miss:" },
    { r = {"MACBETH"}, t = "Would he were here." },
    { r = {"BANQUO"}, d = "Ghost rises again", s = {"Fade"} },
    { r = {"MACBETH"}, t = "To all, and him, we thirst," },
    { r = {"MACBETH"}, t = "And all to all." },
    { r = {"LORDS"}, t = "Our duties, and the pledge." },
    { r = {"MACBETH"}, t = "Avaunt! and quit my sight! let the earth hide thee!" },
    { r = {"MACBETH"}, t = "Thy bones are marrowless, thy blood is cold;" },
    { r = {"MACBETH"}, t = "Thou hast no speculation in those eyes" },
    { r = {"MACBETH"}, t = "Which thou dost glare with!" },
    { r = {"LADY MACBETH"}, t = "Think of this, good peers," },
    { r = {"LADY MACBETH"}, t = "But as a thing of custom: ’tis no other," },
    { r = {"LADY MACBETH"}, t = "Only it spoils the pleasure of the time." },
    { r = {"MACBETH"}, t = "What man dare, I dare:" },
    { r = {"MACBETH"}, t = "Approach thou like the rugged Russian bear," },
    { r = {"MACBETH"}, t = "The arm’d rhinoceros, or th’ Hyrcan tiger;" },
    { r = {"MACBETH"}, t = "Take any shape but that, and my firm nerves" },
    { r = {"MACBETH"}, t = "Shall never tremble: or be alive again," },
    { r = {"MACBETH"}, t = "And dare me to the desert with thy sword;" },
    { r = {"MACBETH"}, t = "If trembling I inhabit then, protest me" },
    { r = {"MACBETH"}, t = "The baby of a girl. Hence, horrible shadow!" },
    { r = {"MACBETH"}, t = "Unreal mock’ry, hence!" },
    { r = {"BANQUO"}, d = "Ghost disappears", s = {"Invisibility", "Stealth", "Shadowmeld"} },
    { r = {"MACBETH"}, t = "Why, so;—being gone," },
    { r = {"MACBETH"}, t = "I am a man again.—Pray you, sit still." },
    { r = {"LADY MACBETH"}, t = "You have displaced the mirth, broke the good meeting" },
    { r = {"LADY MACBETH"}, t = "With most admir’d disorder." },
    { r = {"MACBETH"}, t = "Can such things be," },
    { r = {"MACBETH"}, t = "And overcome us like a summer’s cloud," },
    { r = {"MACBETH"}, t = "Without our special wonder? You make me strange" },
    { r = {"MACBETH"}, t = "Even to the disposition that I owe," },
    { r = {"MACBETH"}, t = "When now I think you can behold such sights," },
    { r = {"MACBETH"}, t = "And keep the natural ruby of your cheeks," },
    { r = {"MACBETH"}, t = "When mine are blanch’d with fear." },
    { r = {"ROSS"}, t = "What sights, my lord?" },
    { r = {"LADY MACBETH"}, t = "I pray you, speak not; he grows worse and worse;" },
    { r = {"LADY MACBETH"}, t = "Question enrages him. At once, good night:—" },
    { r = {"LADY MACBETH"}, t = "Stand not upon the order of your going," },
    { r = {"LADY MACBETH"}, t = "But go at once." },
    { r = {"LENNOX"}, t = "Good night; and better health" },
    { r = {"LENNOX"}, t = "Attend his Majesty!" },
    { r = {"LADY MACBETH"}, t = "A kind good night to all!" },
    { d = "Exeunt all Lords and Attendants" },
    { r = {"MACBETH"}, t = "It will have blood, they say, blood will have blood." },
    { r = {"MACBETH"}, t = "Stones have been known to move, and trees to speak;" },
    { r = {"MACBETH"}, t = "Augurs, and understood relations, have" },
    { r = {"MACBETH"}, t = "By magot-pies, and choughs, and rooks, brought forth" },
    { r = {"MACBETH"}, t = "The secret’st man of blood.—What is the night?" },
    { r = {"LADY MACBETH"}, t = "Almost at odds with morning, which is which." },
    { r = {"MACBETH"}, t = "How say’st thou, that Macduff denies his person" },
    { r = {"MACBETH"}, t = "At our great bidding?" },
    { r = {"LADY MACBETH"}, t = "Did you send to him, sir?" },
    { r = {"MACBETH"}, t = "I hear it by the way; but I will send." },
    { r = {"MACBETH"}, t = "There’s not a one of them but in his house" },
    { r = {"MACBETH"}, t = "I keep a servant fee’d. I will tomorrow" },
    { r = {"MACBETH"}, t = "(And betimes I will) to the Weird Sisters:" },
    { r = {"MACBETH"}, t = "More shall they speak; for now I am bent to know," },
    { r = {"MACBETH"}, t = "By the worst means, the worst. For mine own good," },
    { r = {"MACBETH"}, t = "All causes shall give way: I am in blood" },
    { r = {"MACBETH"}, t = "Stepp’d in so far that, should I wade no more," },
    { r = {"MACBETH"}, t = "Returning were as tedious as go o’er." },
    { r = {"MACBETH"}, t = "Strange things I have in head, that will to hand," },
    { r = {"MACBETH"}, t = "Which must be acted ere they may be scann’d." },
    { r = {"LADY MACBETH"}, t = "You lack the season of all natures, sleep." },
    { r = {"MACBETH"}, t = "Come, we’ll to sleep. My strange and self-abuse" },
    { r = {"MACBETH"}, t = "Is the initiate fear that wants hard use." },
    { r = {"MACBETH"}, t = "We are yet but young in deed." },
    { d = "Exeunt" },
    { d = "Act 3, Scene 5. The heath.", h = true },
    { d = "Thunder. Enter the three Witches meeting Hecate" },
    { r = {"FIRST WITCH"}, t = "Why, how now, Hecate? you look angerly." },
    { r = {"HECATE"}, t = "Have I not reason, beldams as you are," },
    { r = {"HECATE"}, t = "Saucy and overbold? How did you dare" },
    { r = {"HECATE"}, t = "To trade and traffic with Macbeth" },
    { r = {"HECATE"}, t = "In riddles and affairs of death;" },
    { r = {"HECATE"}, t = "And I, the mistress of your charms," },
    { r = {"HECATE"}, t = "The close contriver of all harms," },
    { r = {"HECATE"}, t = "Was never call’d to bear my part," },
    { r = {"HECATE"}, t = "Or show the glory of our art?" },
    { r = {"HECATE"}, t = "And, which is worse, all you have done" },
    { r = {"HECATE"}, t = "Hath been but for a wayward son," },
    { r = {"HECATE"}, t = "Spiteful and wrathful; who, as others do," },
    { r = {"HECATE"}, t = "Loves for his own ends, not for you." },
    { r = {"HECATE"}, t = "But make amends now: get you gone," },
    { r = {"HECATE"}, t = "And at the pit of Acheron" },
    { r = {"HECATE"}, t = "Meet me i’ th’ morning: thither he" },
    { r = {"HECATE"}, t = "Will come to know his destiny." },
    { r = {"HECATE"}, t = "Your vessels and your spells provide," },
    { r = {"HECATE"}, t = "Your charms, and everything beside." },
    { r = {"HECATE"}, t = "I am for th’ air; this night I’ll spend" },
    { r = {"HECATE"}, t = "Unto a dismal and a fatal end." },
    { r = {"HECATE"}, t = "Great business must be wrought ere noon." },
    { r = {"HECATE"}, t = "Upon the corner of the moon" },
    { r = {"HECATE"}, t = "There hangs a vap’rous drop profound;" },
    { r = {"HECATE"}, t = "I’ll catch it ere it come to ground:" },
    { r = {"HECATE"}, t = "And that, distill’d by magic sleights," },
    { r = {"HECATE"}, t = "Shall raise such artificial sprites," },
    { r = {"HECATE"}, t = "As, by the strength of their illusion," },
    { r = {"HECATE"}, t = "Shall draw him on to his confusion." },
    { r = {"HECATE"}, t = "He shall spurn fate, scorn death, and bear" },
    { r = {"HECATE"}, t = "His hopes ’bove wisdom, grace, and fear." },
    { r = {"HECATE"}, t = "And you all know, security" },
    { r = {"HECATE"}, t = "Is mortals’ chiefest enemy." },
    { d = "Music and song within, “Come away, come away” &c" },
    { r = {"HECATE"}, t = "Hark! I am call’d; my little spirit, see," },
    { r = {"HECATE"}, t = "Sits in a foggy cloud and stays for me." },
    { d = "Exit" },
    { r = {"FIRST WITCH"}, t = "Come, let’s make haste; she’ll soon be back again." },
    { d = "Exeunt" },
    { d = "Act 3, Scene 6. Forres. A Room in the Palace.", h = true },
    { d = "Enter Lennox and another Lord" },
    { r = {"LENNOX"}, t = "My former speeches have but hit your thoughts," },
    { r = {"LENNOX"}, t = "Which can interpret farther: only, I say," },
    { r = {"LENNOX"}, t = "Thing’s have been strangely borne. The gracious Duncan" },
    { r = {"LENNOX"}, t = "Was pitied of Macbeth:—marry, he was dead:—" },
    { r = {"LENNOX"}, t = "And the right valiant Banquo walk’d too late;" },
    { r = {"LENNOX"}, t = "Whom, you may say, if’t please you, Fleance kill’d," },
    { r = {"LENNOX"}, t = "For Fleance fled. Men must not walk too late." },
    { r = {"LENNOX"}, t = "Who cannot want the thought, how monstrous" },
    { r = {"LENNOX"}, t = "It was for Malcolm and for Donalbain" },
    { r = {"LENNOX"}, t = "To kill their gracious father? damned fact!" },
    { r = {"LENNOX"}, t = "How it did grieve Macbeth! did he not straight," },
    { r = {"LENNOX"}, t = "In pious rage, the two delinquents tear" },
    { r = {"LENNOX"}, t = "That were the slaves of drink and thralls of sleep?" },
    { r = {"LENNOX"}, t = "Was not that nobly done? Ay, and wisely too;" },
    { r = {"LENNOX"}, t = "For ’twould have anger’d any heart alive," },
    { r = {"LENNOX"}, t = "To hear the men deny’t. So that, I say," },
    { r = {"LENNOX"}, t = "He has borne all things well: and I do think," },
    { r = {"LENNOX"}, t = "That had he Duncan’s sons under his key" },
    { r = {"LENNOX"}, t = "(As, and’t please heaven, he shall not) they should find" },
    { r = {"LENNOX"}, t = "What ’twere to kill a father; so should Fleance." },
    { r = {"LENNOX"}, t = "But, peace!—for from broad words, and ’cause he fail’d" },
    { r = {"LENNOX"}, t = "His presence at the tyrant’s feast, I hear," },
    { r = {"LENNOX"}, t = "Macduff lives in disgrace. Sir, can you tell" },
    { r = {"LENNOX"}, t = "Where he bestows himself?" },
    { r = {"LORD"}, t = "The son of Duncan," },
    { r = {"LORD"}, t = "From whom this tyrant holds the due of birth," },
    { r = {"LORD"}, t = "Lives in the English court and is receiv’d" },
    { r = {"LORD"}, t = "Of the most pious Edward with such grace" },
    { r = {"LORD"}, t = "That the malevolence of fortune nothing" },
    { r = {"LORD"}, t = "Takes from his high respect. Thither Macduff" },
    { r = {"LORD"}, t = "Is gone to pray the holy king, upon his aid" },
    { r = {"LORD"}, t = "To wake Northumberland, and warlike Siward" },
    { r = {"LORD"}, t = "That, by the help of these (with Him above" },
    { r = {"LORD"}, t = "To ratify the work), we may again" },
    { r = {"LORD"}, t = "Give to our tables meat, sleep to our nights;" },
    { r = {"LORD"}, t = "Free from our feasts and banquets bloody knives," },
    { r = {"LORD"}, t = "Do faithful homage, and receive free honours," },
    { r = {"LORD"}, t = "All which we pine for now. And this report" },
    { r = {"LORD"}, t = "Hath so exasperate the King that he" },
    { r = {"LORD"}, t = "Prepares for some attempt of war." },
    { r = {"LENNOX"}, t = "Sent he to Macduff?" },
    { r = {"LORD"}, t = "He did: and with an absolute “Sir, not I,”" },
    { r = {"LORD"}, t = "The cloudy messenger turns me his back," },
    { r = {"LORD"}, t = "And hums, as who should say, “You’ll rue the time" },
    { r = {"LORD"}, t = "That clogs me with this answer.”" },
    { r = {"LENNOX"}, t = "And that well might" },
    { r = {"LENNOX"}, t = "Advise him to a caution, t’ hold what distance" },
    { r = {"LENNOX"}, t = "His wisdom can provide. Some holy angel" },
    { r = {"LENNOX"}, t = "Fly to the court of England, and unfold" },
    { r = {"LENNOX"}, t = "His message ere he come, that a swift blessing" },
    { r = {"LENNOX"}, t = "May soon return to this our suffering country" },
    { r = {"LENNOX"}, t = "Under a hand accurs’d!" },
    { r = {"LORD"}, t = "I’ll send my prayers with him." },
    { d = "Exeunt" },
    { d = "Act 4, Scene 1. A dark Cave. In the middle, a Cauldron Boiling.", h = true },
    { d = "Thunder. Enter the three Witches" },
    { r = {"FIRST WITCH"}, t = "Thrice the brinded cat hath mew’d." },
    { r = {"SECOND WITCH"}, t = "Thrice, and once the hedge-pig whin’d." },
    { r = {"THIRD WITCH"}, t = "Harpier cries:—’Tis time, ’tis time." },
    { r = {"FIRST WITCH"}, t = "Round about the cauldron go;" },
    { r = {"FIRST WITCH"}, t = "In the poison’d entrails throw.—" },
    { r = {"FIRST WITCH"}, t = "Toad, that under cold stone" },
    { r = {"FIRST WITCH"}, t = "Days and nights has thirty-one" },
    { r = {"FIRST WITCH"}, t = "Swelter’d venom sleeping got," },
    { r = {"FIRST WITCH"}, t = "Boil thou first i’ th’ charmed pot!" },
    { r = {"ALL"}, t = "Double, double, toil and trouble;" },
    { r = {"ALL"}, t = "Fire, burn; and cauldron, bubble." },
    { r = {"SECOND WITCH"}, t = "Fillet of a fenny snake," },
    { r = {"SECOND WITCH"}, t = "In the cauldron boil and bake;" },
    { r = {"SECOND WITCH"}, t = "Eye of newt, and toe of frog," },
    { r = {"SECOND WITCH"}, t = "Wool of bat, and tongue of dog," },
    { r = {"SECOND WITCH"}, t = "Adder’s fork, and blind-worm’s sting," },
    { r = {"SECOND WITCH"}, t = "Lizard’s leg, and howlet’s wing," },
    { r = {"SECOND WITCH"}, t = "For a charm of powerful trouble," },
    { r = {"SECOND WITCH"}, t = "Like a hell-broth boil and bubble." },
    { r = {"ALL"}, t = "Double, double, toil and trouble;" },
    { r = {"ALL"}, t = "Fire, burn; and cauldron, bubble." },
    { r = {"THIRD WITCH"}, t = "Scale of dragon, tooth of wolf," },
    { r = {"THIRD WITCH"}, t = "Witch’s mummy, maw and gulf" },
    { r = {"THIRD WITCH"}, t = "Of the ravin’d salt-sea shark," },
    { r = {"THIRD WITCH"}, t = "Root of hemlock digg’d i’ th’ dark," },
    { r = {"THIRD WITCH"}, t = "Liver of blaspheming Jew," },
    { r = {"THIRD WITCH"}, t = "Gall of goat, and slips of yew" },
    { r = {"THIRD WITCH"}, t = "Sliver’d in the moon’s eclipse," },
    { r = {"THIRD WITCH"}, t = "Nose of Turk, and Tartar’s lips," },
    { r = {"THIRD WITCH"}, t = "Finger of birth-strangled babe" },
    { r = {"THIRD WITCH"}, t = "Ditch-deliver’d by a drab," },
    { r = {"THIRD WITCH"}, t = "Make the gruel thick and slab:" },
    { r = {"THIRD WITCH"}, t = "Add thereto a tiger’s chaudron," },
    { r = {"THIRD WITCH"}, t = "For th’ ingredients of our cauldron." },
    { r = {"ALL"}, t = "Double, double, toil and trouble;" },
    { r = {"ALL"}, t = "Fire, burn; and cauldron, bubble." },
    { r = {"SECOND WITCH"}, t = "Cool it with a baboon’s blood." },
    { r = {"SECOND WITCH"}, t = "Then the charm is firm and good." },
    { d = "Enter Hecate" },
    { r = {"HECATE"}, t = "O, well done! I commend your pains," },
    { r = {"HECATE"}, t = "And everyone shall share i’ th’ gains." },
    { r = {"HECATE"}, t = "And now about the cauldron sing," },
    { r = {"HECATE"}, t = "Like elves and fairies in a ring," },
    { r = {"HECATE"}, t = "Enchanting all that you put in." },
    { d = "Music and a song: “Black Spirits,” &c" },
    { d = "Exit Hecate" },
    { r = {"SECOND WITCH"}, t = "By the pricking of my thumbs," },
    { r = {"SECOND WITCH"}, t = "Something wicked this way comes." },
    { r = {"SECOND WITCH"}, t = "Open, locks," },
    { r = {"SECOND WITCH"}, t = "Whoever knocks!" },
    { d = "Enter Macbeth" },
    { r = {"MACBETH"}, t = "How now, you secret, black, and midnight hags!" },
    { r = {"MACBETH"}, t = "What is’t you do?" },
    { r = {"ALL"}, t = "A deed without a name." },
    { r = {"MACBETH"}, t = "I conjure you, by that which you profess," },
    { r = {"MACBETH"}, t = "(Howe’er you come to know it) answer me:" },
    { r = {"MACBETH"}, t = "Though you untie the winds, and let them fight" },
    { r = {"MACBETH"}, t = "Against the churches; though the yesty waves" },
    { r = {"MACBETH"}, t = "Confound and swallow navigation up;" },
    { r = {"MACBETH"}, t = "Though bladed corn be lodg’d, and trees blown down;" },
    { r = {"MACBETH"}, t = "Though castles topple on their warders’ heads;" },
    { r = {"MACBETH"}, t = "Though palaces and pyramids do slope" },
    { r = {"MACBETH"}, t = "Their heads to their foundations; though the treasure" },
    { r = {"MACBETH"}, t = "Of nature’s germens tumble all together," },
    { r = {"MACBETH"}, t = "Even till destruction sicken, answer me" },
    { r = {"MACBETH"}, t = "To what I ask you." },
    { r = {"FIRST WITCH"}, t = "Speak." },
    { r = {"SECOND WITCH"}, t = "Demand." },
    { r = {"THIRD WITCH"}, t = "We’ll answer." },
    { r = {"FIRST WITCH"}, t = "Say, if thou’dst rather hear it from our mouths," },
    { r = {"FIRST WITCH"}, t = "Or from our masters?" },
    { r = {"MACBETH"}, t = "Call ’em, let me see ’em." },
    { r = {"FIRST WITCH"}, t = "Pour in sow’s blood, that hath eaten" },
    { r = {"FIRST WITCH"}, t = "Her nine farrow; grease that’s sweaten" },
    { r = {"FIRST WITCH"}, t = "From the murderer’s gibbet throw" },
    { r = {"FIRST WITCH"}, t = "Into the flame." },
    { r = {"ALL"}, t = "Come, high or low;" },
    { r = {"ALL"}, t = "Thyself and office deftly show!" },
    { r = {"APPARITION"}, d = "Thunder. An Apparition of an armed Head rises", s = {"Fade"} },
    { r = {"MACBETH"}, t = "Tell me, thou unknown power," },
    { r = {"FIRST WITCH"}, t = "He knows thy thought:" },
    { r = {"FIRST WITCH"}, t = "Hear his speech, but say thou naught." },
    { r = {"APPARITION"}, t = "Macbeth! Macbeth! Macbeth! Beware Macduff;" },
    { r = {"APPARITION"}, t = "Beware the Thane of Fife.—Dismiss me.—Enough." },
    { r = {"APPARITION"}, d = "Descends", s = {"Invisibility", "Stealth", "Shadowmeld"} },
    { r = {"MACBETH"}, t = "Whate’er thou art, for thy good caution, thanks;" },
    { r = {"MACBETH"}, t = "Thou hast harp’d my fear aright.—But one word more." },
    { r = {"FIRST WITCH"}, t = "He will not be commanded. Here’s another," },
    { r = {"FIRST WITCH"}, t = "More potent than the first." },
    { r = {"APPARITION"}, d = "Thunder. An Apparition of a bloody Child rises", s = {"Fade"} },
    { r = {"APPARITION"}, t = "Macbeth! Macbeth! Macbeth!" },
    { r = {"MACBETH"}, t = "Had I three ears, I’d hear thee." },
    { r = {"APPARITION"}, t = "Be bloody, bold, and resolute. Laugh to scorn" },
    { r = {"APPARITION"}, t = "The power of man, for none of woman born" },
    { r = {"APPARITION"}, t = "Shall harm Macbeth." },
    { r = {"APPARITION"}, d = "Descends", s = {"Invisibility", "Stealth", "Shadowmeld"} },
    { r = {"MACBETH"}, t = "Then live, Macduff: what need I fear of thee?" },
    { r = {"MACBETH"}, t = "But yet I’ll make assurance double sure," },
    { r = {"MACBETH"}, t = "And take a bond of fate. Thou shalt not live;" },
    { r = {"MACBETH"}, t = "That I may tell pale-hearted fear it lies," },
    { r = {"MACBETH"}, t = "And sleep in spite of thunder." },
    { r = {"APPARITION"}, d = "Thunder. An Apparition of a Child crowned, with a tree in his hand, rises", s = {"Fade"} },
    { r = {"MACBETH"}, t = "What is this," },
    { r = {"MACBETH"}, t = "That rises like the issue of a king," },
    { r = {"MACBETH"}, t = "And wears upon his baby brow the round" },
    { r = {"MACBETH"}, t = "And top of sovereignty?" },
    { r = {"ALL"}, t = "Listen, but speak not to’t." },
    { r = {"APPARITION"}, t = "Be lion-mettled, proud, and take no care" },
    { r = {"APPARITION"}, t = "Who chafes, who frets, or where conspirers are:" },
    { r = {"APPARITION"}, t = "Macbeth shall never vanquish’d be, until" },
    { r = {"APPARITION"}, t = "Great Birnam wood to high Dunsinane hill" },
    { r = {"APPARITION"}, t = "Shall come against him." },
    { r = {"APPARITION"}, d = "Descends", s = {"Invisibility", "Stealth", "Shadowmeld"} },
    { r = {"MACBETH"}, t = "That will never be:" },
    { r = {"MACBETH"}, t = "Who can impress the forest; bid the tree" },
    { r = {"MACBETH"}, t = "Unfix his earth-bound root? Sweet bodements, good!" },
    { r = {"MACBETH"}, t = "Rebellious head, rise never till the wood" },
    { r = {"MACBETH"}, t = "Of Birnam rise, and our high-plac’d Macbeth" },
    { r = {"MACBETH"}, t = "Shall live the lease of nature, pay his breath" },
    { r = {"MACBETH"}, t = "To time and mortal custom.—Yet my heart" },
    { r = {"MACBETH"}, t = "Throbs to know one thing: tell me, if your art" },
    { r = {"MACBETH"}, t = "Can tell so much, shall Banquo’s issue ever" },
    { r = {"MACBETH"}, t = "Reign in this kingdom?" },
    { r = {"ALL"}, t = "Seek to know no more." },
    { r = {"MACBETH"}, t = "I will be satisfied: deny me this," },
    { r = {"MACBETH"}, t = "And an eternal curse fall on you! Let me know." },
    { r = {"MACBETH"}, t = "Why sinks that cauldron? and what noise is this?" },
    { d = "Hautboys" },
    { r = {"FIRST WITCH"}, t = "Show!" },
    { r = {"SECOND WITCH"}, t = "Show!" },
    { r = {"THIRD WITCH"}, t = "Show!" },
    { r = {"ALL"}, t = "Show his eyes, and grieve his heart;" },
    { r = {"ALL"}, t = "Come like shadows, so depart!" },
    { r = {"BANQUO"}, d = "A show of eight kings appear, and pass over in order, the last with a glass in his hand; Banquo following", s = {"Fade"} },
    { r = {"MACBETH"}, t = "Thou are too like the spirit of Banquo. Down!" },
    { r = {"MACBETH"}, t = "Thy crown does sear mine eyeballs:—and thy hair," },
    { r = {"MACBETH"}, t = "Thou other gold-bound brow, is like the first." },
    { r = {"MACBETH"}, t = "A third is like the former.—Filthy hags!" },
    { r = {"MACBETH"}, t = "Why do you show me this?—A fourth!—Start, eyes!" },
    { r = {"MACBETH"}, t = "What, will the line stretch out to th’ crack of doom?" },
    { r = {"MACBETH"}, t = "Another yet!—A seventh!—I’ll see no more:—" },
    { r = {"MACBETH"}, t = "And yet the eighth appears, who bears a glass" },
    { r = {"MACBETH"}, t = "Which shows me many more; and some I see" },
    { r = {"MACBETH"}, t = "That twofold balls and treble sceptres carry." },
    { r = {"MACBETH"}, t = "Horrible sight!—Now I see ’tis true;" },
    { r = {"MACBETH"}, t = "For the blood-bolter’d Banquo smiles upon me," },
    { r = {"MACBETH"}, t = "And points at them for his.—What! is this so?" },
    { r = {"FIRST WITCH"}, t = "Ay, sir, all this is so:—but why" },
    { r = {"FIRST WITCH"}, t = "Stands Macbeth thus amazedly?—" },
    { r = {"FIRST WITCH"}, t = "Come, sisters, cheer we up his sprites," },
    { r = {"FIRST WITCH"}, t = "And show the best of our delights." },
    { r = {"FIRST WITCH"}, t = "I’ll charm the air to give a sound," },
    { r = {"FIRST WITCH"}, t = "While you perform your antic round;" },
    { r = {"FIRST WITCH"}, t = "That this great king may kindly say," },
    { r = {"FIRST WITCH"}, t = "Our duties did his welcome pay." },
    { d = "Music. The Witches dance, and vanish" },
    { r = {"MACBETH"}, t = "Where are they? Gone?—Let this pernicious hour" },
    { r = {"MACBETH"}, t = "Stand aye accursed in the calendar!—" },
    { r = {"MACBETH"}, t = "Come in, without there!" },
    { d = "Enter Lennox" },
    { r = {"LENNOX"}, t = "What’s your Grace’s will?" },
    { r = {"MACBETH"}, t = "Saw you the Weird Sisters?" },
    { r = {"LENNOX"}, t = "No, my lord." },
    { r = {"MACBETH"}, t = "Came they not by you?" },
    { r = {"LENNOX"}, t = "No, indeed, my lord." },
    { r = {"MACBETH"}, t = "Infected be the air whereon they ride;" },
    { r = {"MACBETH"}, t = "And damn’d all those that trust them!—I did hear" },
    { r = {"MACBETH"}, t = "The galloping of horse: who was’t came by?" },
    { r = {"LENNOX"}, t = "’Tis two or three, my lord, that bring you word" },
    { r = {"LENNOX"}, t = "Macduff is fled to England." },
    { r = {"MACBETH"}, t = "Fled to England!" },
    { r = {"LENNOX"}, t = "Ay, my good lord." },
    { r = {"MACBETH"}, t = "Time, thou anticipat’st my dread exploits:" },
    { r = {"MACBETH"}, t = "The flighty purpose never is o’ertook" },
    { r = {"MACBETH"}, t = "Unless the deed go with it. From this moment" },
    { r = {"MACBETH"}, t = "The very firstlings of my heart shall be" },
    { r = {"MACBETH"}, t = "The firstlings of my hand. And even now," },
    { r = {"MACBETH"}, t = "To crown my thoughts with acts, be it thought and done:" },
    { r = {"MACBETH"}, t = "The castle of Macduff I will surprise;" },
    { r = {"MACBETH"}, t = "Seize upon Fife; give to th’ edge o’ th’ sword" },
    { r = {"MACBETH"}, t = "His wife, his babes, and all unfortunate souls" },
    { r = {"MACBETH"}, t = "That trace him in his line. No boasting like a fool;" },
    { r = {"MACBETH"}, t = "This deed I’ll do before this purpose cool:" },
    { r = {"MACBETH"}, t = "But no more sights!—Where are these gentlemen?" },
    { r = {"MACBETH"}, t = "Come, bring me where they are." },
    { d = "Exeunt" },
    { d = "Act 4, Scene 2. Fife. A Room in Macduff’s Castle.", h = true },
    { d = "Enter Lady Macduff her Son and Ross" },
    { r = {"LADY MACDUFF"}, t = "What had he done, to make him fly the land?" },
    { r = {"ROSS"}, t = "You must have patience, madam." },
    { r = {"LADY MACDUFF"}, t = "He had none:" },
    { r = {"LADY MACDUFF"}, t = "His flight was madness: when our actions do not," },
    { r = {"LADY MACDUFF"}, t = "Our fears do make us traitors." },
    { r = {"ROSS"}, t = "You know not" },
    { r = {"ROSS"}, t = "Whether it was his wisdom or his fear." },
    { r = {"LADY MACDUFF"}, t = "Wisdom! to leave his wife, to leave his babes," },
    { r = {"LADY MACDUFF"}, t = "His mansion, and his titles, in a place" },
    { r = {"LADY MACDUFF"}, t = "From whence himself does fly? He loves us not:" },
    { r = {"LADY MACDUFF"}, t = "He wants the natural touch; for the poor wren," },
    { r = {"LADY MACDUFF"}, t = "The most diminutive of birds, will fight," },
    { r = {"LADY MACDUFF"}, t = "Her young ones in her nest, against the owl." },
    { r = {"LADY MACDUFF"}, t = "All is the fear, and nothing is the love;" },
    { r = {"LADY MACDUFF"}, t = "As little is the wisdom, where the flight" },
    { r = {"LADY MACDUFF"}, t = "So runs against all reason." },
    { r = {"ROSS"}, t = "My dearest coz," },
    { r = {"ROSS"}, t = "I pray you, school yourself: but, for your husband," },
    { r = {"ROSS"}, t = "He is noble, wise, judicious, and best knows" },
    { r = {"ROSS"}, t = "The fits o’ th’ season. I dare not speak much further:" },
    { r = {"ROSS"}, t = "But cruel are the times, when we are traitors," },
    { r = {"ROSS"}, t = "And do not know ourselves; when we hold rumour" },
    { r = {"ROSS"}, t = "From what we fear, yet know not what we fear," },
    { r = {"ROSS"}, t = "But float upon a wild and violent sea" },
    { r = {"ROSS"}, t = "Each way and move—I take my leave of you:" },
    { r = {"ROSS"}, t = "Shall not be long but I’ll be here again." },
    { r = {"ROSS"}, t = "Things at the worst will cease, or else climb upward" },
    { r = {"ROSS"}, t = "To what they were before.—My pretty cousin," },
    { r = {"ROSS"}, t = "Blessing upon you!" },
    { r = {"LADY MACDUFF"}, t = "Father’d he is, and yet he’s fatherless." },
    { r = {"ROSS"}, t = "I am so much a fool, should I stay longer," },
    { r = {"ROSS"}, t = "It would be my disgrace and your discomfort:" },
    { r = {"ROSS"}, t = "I take my leave at once." },
    { d = "Exit" },
    { r = {"LADY MACDUFF"}, t = "Sirrah, your father’s dead." },
    { r = {"LADY MACDUFF"}, t = "And what will you do now? How will you live?" },
    { r = {"BOY"}, t = "As birds do, mother." },
    { r = {"LADY MACDUFF"}, t = "What, with worms and flies?" },
    { r = {"BOY"}, t = "With what I get, I mean; and so do they." },
    { r = {"LADY MACDUFF"}, t = "Poor bird! thou’dst never fear the net nor lime," },
    { r = {"LADY MACDUFF"}, t = "The pit-fall nor the gin." },
    { r = {"BOY"}, t = "Why should I, mother? Poor birds they are not set for." },
    { r = {"BOY"}, t = "My father is not dead, for all your saying." },
    { r = {"LADY MACDUFF"}, t = "Yes, he is dead: how wilt thou do for a father?" },
    { r = {"BOY"}, t = "Nay, how will you do for a husband?" },
    { r = {"LADY MACDUFF"}, t = "Why, I can buy me twenty at any market." },
    { r = {"BOY"}, t = "Then you’ll buy ’em to sell again." },
    { r = {"LADY MACDUFF"}, t = "Thou speak’st with all thy wit;" },
    { r = {"LADY MACDUFF"}, t = "And yet, i’ faith, with wit enough for thee." },
    { r = {"BOY"}, t = "Was my father a traitor, mother?" },
    { r = {"LADY MACDUFF"}, t = "Ay, that he was." },
    { r = {"BOY"}, t = "What is a traitor?" },
    { r = {"LADY MACDUFF"}, t = "Why, one that swears and lies." },
    { r = {"BOY"}, t = "And be all traitors that do so?" },
    { r = {"LADY MACDUFF"}, t = "Every one that does so is a traitor, and must be hanged." },
    { r = {"BOY"}, t = "And must they all be hanged that swear and lie?" },
    { r = {"LADY MACDUFF"}, t = "Every one." },
    { r = {"BOY"}, t = "Who must hang them?" },
    { r = {"LADY MACDUFF"}, t = "Why, the honest men." },
    { r = {"BOY"}, t = "Then the liars and swearers are fools: for there are liars and swearers enow to beat the honest men and hang up them." },
    { r = {"LADY MACDUFF"}, t = "Now, God help thee, poor monkey! But how wilt thou do for a father?" },
    { r = {"BOY"}, t = "If he were dead, you’ld weep for him: if you would not, it were a good sign that I should quickly have a new father." },
    { r = {"LADY MACDUFF"}, t = "Poor prattler, how thou talk’st!" },
    { d = "Enter a Messenger" },
    { r = {"MESSENGER"}, t = "Bless you, fair dame! I am not to you known," },
    { r = {"MESSENGER"}, t = "Though in your state of honour I am perfect." },
    { r = {"MESSENGER"}, t = "I doubt some danger does approach you nearly:" },
    { r = {"MESSENGER"}, t = "If you will take a homely man’s advice," },
    { r = {"MESSENGER"}, t = "Be not found here; hence, with your little ones." },
    { r = {"MESSENGER"}, t = "To fright you thus, methinks, I am too savage;" },
    { r = {"MESSENGER"}, t = "To do worse to you were fell cruelty," },
    { r = {"MESSENGER"}, t = "Which is too nigh your person. Heaven preserve you!" },
    { r = {"MESSENGER"}, t = "I dare abide no longer." },
    { d = "Exit" },
    { r = {"LADY MACDUFF"}, t = "Whither should I fly?" },
    { r = {"LADY MACDUFF"}, t = "I have done no harm. But I remember now" },
    { r = {"LADY MACDUFF"}, t = "I am in this earthly world, where to do harm" },
    { r = {"LADY MACDUFF"}, t = "Is often laudable; to do good sometime" },
    { r = {"LADY MACDUFF"}, t = "Accounted dangerous folly:  why then, alas," },
    { r = {"LADY MACDUFF"}, t = "Do I put up that womanly defence," },
    { r = {"LADY MACDUFF"}, t = "To say I have done no harm? What are these faces?" },
    { d = "Enter Murderers" },
    { r = {"FIRST MURDERER"}, t = "Where is your husband?" },
    { r = {"LADY MACDUFF"}, t = "I hope, in no place so unsanctified" },
    { r = {"LADY MACDUFF"}, t = "Where such as thou mayst find him." },
    { r = {"FIRST MURDERER"}, t = "He’s a traitor." },
    { r = {"BOY"}, t = "Thou liest, thou shag-ear’d villain!" },
    { r = {"FIRST MURDERER"}, t = "What, you egg!" },
    { d = "Stabbing him" },
    { r = {"FIRST MURDERER"}, t = "Young fry of treachery!" },
    { r = {"BOY"}, t = "He has kill’d me, mother:" },
    { r = {"BOY"}, t = "Run away, I pray you!" },
    { r = {"BOY"}, d = "Dies. Exit Lady Macduff, crying “Murder!” and pursued by the Murderers", e = "/lie", s = {"Feign Death"} },
    { d = "Act 4, Scene 3. England. Before the King’s Palace.", h = true },
    { d = "Enter Malcolm and Macduff" },
    { r = {"MALCOLM"}, t = "Let us seek out some desolate shade and there" },
    { r = {"MALCOLM"}, t = "Weep our sad bosoms empty." },
    { r = {"MACDUFF"}, t = "Let us rather" },
    { r = {"MACDUFF"}, t = "Hold fast the mortal sword, and, like good men," },
    { r = {"MACDUFF"}, t = "Bestride our down-fall’n birthdom. Each new morn" },
    { r = {"MACDUFF"}, t = "New widows howl, new orphans cry; new sorrows" },
    { r = {"MACDUFF"}, t = "Strike heaven on the face, that it resounds" },
    { r = {"MACDUFF"}, t = "As if it felt with Scotland, and yell’d out" },
    { r = {"MACDUFF"}, t = "Like syllable of dolour." },
    { r = {"MALCOLM"}, t = "What I believe, I’ll wail;" },
    { r = {"MALCOLM"}, t = "What know, believe; and what I can redress," },
    { r = {"MALCOLM"}, t = "As I shall find the time to friend, I will." },
    { r = {"MALCOLM"}, t = "What you have spoke, it may be so, perchance." },
    { r = {"MALCOLM"}, t = "This tyrant, whose sole name blisters our tongues," },
    { r = {"MALCOLM"}, t = "Was once thought honest: you have loved him well;" },
    { r = {"MALCOLM"}, t = "He hath not touch’d you yet. I am young; but something" },
    { r = {"MALCOLM"}, t = "You may deserve of him through me; and wisdom" },
    { r = {"MALCOLM"}, t = "To offer up a weak, poor, innocent lamb" },
    { r = {"MALCOLM"}, t = "To appease an angry god." },
    { r = {"MACDUFF"}, t = "I am not treacherous." },
    { r = {"MALCOLM"}, t = "But Macbeth is." },
    { r = {"MALCOLM"}, t = "A good and virtuous nature may recoil" },
    { r = {"MALCOLM"}, t = "In an imperial charge. But I shall crave your pardon." },
    { r = {"MALCOLM"}, t = "That which you are, my thoughts cannot transpose." },
    { r = {"MALCOLM"}, t = "Angels are bright still, though the brightest fell:" },
    { r = {"MALCOLM"}, t = "Though all things foul would wear the brows of grace," },
    { r = {"MALCOLM"}, t = "Yet grace must still look so." },
    { r = {"MACDUFF"}, t = "I have lost my hopes." },
    { r = {"MALCOLM"}, t = "Perchance even there where I did find my doubts." },
    { r = {"MALCOLM"}, t = "Why in that rawness left you wife and child," },
    { r = {"MALCOLM"}, t = "Those precious motives, those strong knots of love," },
    { r = {"MALCOLM"}, t = "Without leave-taking?—I pray you," },
    { r = {"MALCOLM"}, t = "Let not my jealousies be your dishonours," },
    { r = {"MALCOLM"}, t = "But mine own safeties. You may be rightly just," },
    { r = {"MALCOLM"}, t = "Whatever I shall think." },
    { r = {"MACDUFF"}, t = "Bleed, bleed, poor country!" },
    { r = {"MACDUFF"}, t = "Great tyranny, lay thou thy basis sure," },
    { r = {"MACDUFF"}, t = "For goodness dare not check thee! wear thou thy wrongs;" },
    { r = {"MACDUFF"}, t = "The title is affeer’d.—Fare thee well, lord:" },
    { r = {"MACDUFF"}, t = "I would not be the villain that thou think’st" },
    { r = {"MACDUFF"}, t = "For the whole space that’s in the tyrant’s grasp" },
    { r = {"MACDUFF"}, t = "And the rich East to boot." },
    { r = {"MALCOLM"}, t = "Be not offended:" },
    { r = {"MALCOLM"}, t = "I speak not as in absolute fear of you." },
    { r = {"MALCOLM"}, t = "I think our country sinks beneath the yoke;" },
    { r = {"MALCOLM"}, t = "It weeps, it bleeds; and each new day a gash" },
    { r = {"MALCOLM"}, t = "Is added to her wounds. I think, withal," },
    { r = {"MALCOLM"}, t = "There would be hands uplifted in my right;" },
    { r = {"MALCOLM"}, t = "And here, from gracious England, have I offer" },
    { r = {"MALCOLM"}, t = "Of goodly thousands: but, for all this," },
    { r = {"MALCOLM"}, t = "When I shall tread upon the tyrant’s head," },
    { r = {"MALCOLM"}, t = "Or wear it on my sword, yet my poor country" },
    { r = {"MALCOLM"}, t = "Shall have more vices than it had before," },
    { r = {"MALCOLM"}, t = "More suffer, and more sundry ways than ever," },
    { r = {"MALCOLM"}, t = "By him that shall succeed." },
    { r = {"MACDUFF"}, t = "What should he be?" },
    { r = {"MALCOLM"}, t = "It is myself I mean; in whom I know" },
    { r = {"MALCOLM"}, t = "All the particulars of vice so grafted" },
    { r = {"MALCOLM"}, t = "That, when they shall be open’d, black Macbeth" },
    { r = {"MALCOLM"}, t = "Will seem as pure as snow; and the poor state" },
    { r = {"MALCOLM"}, t = "Esteem him as a lamb, being compar’d" },
    { r = {"MALCOLM"}, t = "With my confineless harms." },
    { r = {"MACDUFF"}, t = "Not in the legions" },
    { r = {"MACDUFF"}, t = "Of horrid hell can come a devil more damn’d" },
    { r = {"MACDUFF"}, t = "In evils to top Macbeth." },
    { r = {"MALCOLM"}, t = "I grant him bloody," },
    { r = {"MALCOLM"}, t = "Luxurious, avaricious, false, deceitful," },
    { r = {"MALCOLM"}, t = "Sudden, malicious, smacking of every sin" },
    { r = {"MALCOLM"}, t = "That has a name: but there’s no bottom, none," },
    { r = {"MALCOLM"}, t = "In my voluptuousness: your wives, your daughters," },
    { r = {"MALCOLM"}, t = "Your matrons, and your maids, could not fill up" },
    { r = {"MALCOLM"}, t = "The cistern of my lust; and my desire" },
    { r = {"MALCOLM"}, t = "All continent impediments would o’erbear," },
    { r = {"MALCOLM"}, t = "That did oppose my will: better Macbeth" },
    { r = {"MALCOLM"}, t = "Than such an one to reign." },
    { r = {"MACDUFF"}, t = "Boundless intemperance" },
    { r = {"MACDUFF"}, t = "In nature is a tyranny; it hath been" },
    { r = {"MACDUFF"}, t = "Th’ untimely emptying of the happy throne," },
    { r = {"MACDUFF"}, t = "And fall of many kings. But fear not yet" },
    { r = {"MACDUFF"}, t = "To take upon you what is yours: you may" },
    { r = {"MACDUFF"}, t = "Convey your pleasures in a spacious plenty," },
    { r = {"MACDUFF"}, t = "And yet seem cold—the time you may so hoodwink." },
    { r = {"MACDUFF"}, t = "We have willing dames enough; there cannot be" },
    { r = {"MACDUFF"}, t = "That vulture in you, to devour so many" },
    { r = {"MACDUFF"}, t = "As will to greatness dedicate themselves," },
    { r = {"MACDUFF"}, t = "Finding it so inclin’d." },
    { r = {"MALCOLM"}, t = "With this there grows" },
    { r = {"MALCOLM"}, t = "In my most ill-compos’d affection such" },
    { r = {"MALCOLM"}, t = "A staunchless avarice, that, were I king," },
    { r = {"MALCOLM"}, t = "I should cut off the nobles for their lands;" },
    { r = {"MALCOLM"}, t = "Desire his jewels, and this other’s house:" },
    { r = {"MALCOLM"}, t = "And my more-having would be as a sauce" },
    { r = {"MALCOLM"}, t = "To make me hunger more; that I should forge" },
    { r = {"MALCOLM"}, t = "Quarrels unjust against the good and loyal," },
    { r = {"MALCOLM"}, t = "Destroying them for wealth." },
    { r = {"MACDUFF"}, t = "This avarice" },
    { r = {"MACDUFF"}, t = "Sticks deeper; grows with more pernicious root" },
    { r = {"MACDUFF"}, t = "Than summer-seeming lust; and it hath been" },
    { r = {"MACDUFF"}, t = "The sword of our slain kings: yet do not fear;" },
    { r = {"MACDUFF"}, t = "Scotland hath foisons to fill up your will," },
    { r = {"MACDUFF"}, t = "Of your mere own. All these are portable," },
    { r = {"MACDUFF"}, t = "With other graces weigh’d." },
    { r = {"MALCOLM"}, t = "But I have none: the king-becoming graces," },
    { r = {"MALCOLM"}, t = "As justice, verity, temp’rance, stableness," },
    { r = {"MALCOLM"}, t = "Bounty, perseverance, mercy, lowliness," },
    { r = {"MALCOLM"}, t = "Devotion, patience, courage, fortitude," },
    { r = {"MALCOLM"}, t = "I have no relish of them; but abound" },
    { r = {"MALCOLM"}, t = "In the division of each several crime," },
    { r = {"MALCOLM"}, t = "Acting it many ways. Nay, had I power, I should" },
    { r = {"MALCOLM"}, t = "Pour the sweet milk of concord into hell," },
    { r = {"MALCOLM"}, t = "Uproar the universal peace, confound" },
    { r = {"MALCOLM"}, t = "All unity on earth." },
    { r = {"MACDUFF"}, t = "O Scotland, Scotland!" },
    { r = {"MALCOLM"}, t = "If such a one be fit to govern, speak:" },
    { r = {"MALCOLM"}, t = "I am as I have spoken." },
    { r = {"MACDUFF"}, t = "Fit to govern?" },
    { r = {"MACDUFF"}, t = "No, not to live.—O nation miserable," },
    { r = {"MACDUFF"}, t = "With an untitled tyrant bloody-scepter’d," },
    { r = {"MACDUFF"}, t = "When shalt thou see thy wholesome days again," },
    { r = {"MACDUFF"}, t = "Since that the truest issue of thy throne" },
    { r = {"MACDUFF"}, t = "By his own interdiction stands accus’d," },
    { r = {"MACDUFF"}, t = "And does blaspheme his breed? Thy royal father" },
    { r = {"MACDUFF"}, t = "Was a most sainted king. The queen that bore thee," },
    { r = {"MACDUFF"}, t = "Oft’ner upon her knees than on her feet," },
    { r = {"MACDUFF"}, t = "Died every day she lived. Fare thee well!" },
    { r = {"MACDUFF"}, t = "These evils thou repeat’st upon thyself" },
    { r = {"MACDUFF"}, t = "Have banish’d me from Scotland.—O my breast," },
    { r = {"MACDUFF"}, t = "Thy hope ends here!" },
    { r = {"MALCOLM"}, t = "Macduff, this noble passion," },
    { r = {"MALCOLM"}, t = "Child of integrity, hath from my soul" },
    { r = {"MALCOLM"}, t = "Wiped the black scruples, reconcil’d my thoughts" },
    { r = {"MALCOLM"}, t = "To thy good truth and honour. Devilish Macbeth" },
    { r = {"MALCOLM"}, t = "By many of these trains hath sought to win me" },
    { r = {"MALCOLM"}, t = "Into his power, and modest wisdom plucks me" },
    { r = {"MALCOLM"}, t = "From over-credulous haste: but God above" },
    { r = {"MALCOLM"}, t = "Deal between thee and me! for even now" },
    { r = {"MALCOLM"}, t = "I put myself to thy direction, and" },
    { r = {"MALCOLM"}, t = "Unspeak mine own detraction; here abjure" },
    { r = {"MALCOLM"}, t = "The taints and blames I laid upon myself," },
    { r = {"MALCOLM"}, t = "For strangers to my nature. I am yet" },
    { r = {"MALCOLM"}, t = "Unknown to woman; never was forsworn;" },
    { r = {"MALCOLM"}, t = "Scarcely have coveted what was mine own;" },
    { r = {"MALCOLM"}, t = "At no time broke my faith; would not betray" },
    { r = {"MALCOLM"}, t = "The devil to his fellow; and delight" },
    { r = {"MALCOLM"}, t = "No less in truth than life: my first false speaking" },
    { r = {"MALCOLM"}, t = "Was this upon myself. What I am truly," },
    { r = {"MALCOLM"}, t = "Is thine and my poor country’s to command:" },
    { r = {"MALCOLM"}, t = "Whither, indeed, before thy here-approach," },
    { r = {"MALCOLM"}, t = "Old Siward, with ten thousand warlike men," },
    { r = {"MALCOLM"}, t = "Already at a point, was setting forth." },
    { r = {"MALCOLM"}, t = "Now we’ll together, and the chance of goodness" },
    { r = {"MALCOLM"}, t = "Be like our warranted quarrel. Why are you silent?" },
    { r = {"MACDUFF"}, t = "Such welcome and unwelcome things at once" },
    { r = {"MACDUFF"}, t = "’Tis hard to reconcile." },
    { d = "Enter a Doctor" },
    { r = {"MALCOLM"}, t = "Well; more anon.—Comes the King forth, I pray you?" },
    { r = {"DOCTOR"}, t = "Ay, sir. There are a crew of wretched souls" },
    { r = {"DOCTOR"}, t = "That stay his cure: their malady convinces" },
    { r = {"DOCTOR"}, t = "The great assay of art; but at his touch," },
    { r = {"DOCTOR"}, t = "Such sanctity hath heaven given his hand," },
    { r = {"DOCTOR"}, t = "They presently amend." },
    { r = {"MALCOLM"}, t = "I thank you, doctor." },
    { d = "Exit Doctor" },
    { r = {"MACDUFF"}, t = "What’s the disease he means?" },
    { r = {"MALCOLM"}, t = "’Tis call’d the evil:" },
    { r = {"MALCOLM"}, t = "A most miraculous work in this good king;" },
    { r = {"MALCOLM"}, t = "Which often, since my here-remain in England," },
    { r = {"MALCOLM"}, t = "I have seen him do. How he solicits heaven," },
    { r = {"MALCOLM"}, t = "Himself best knows, but strangely-visited people," },
    { r = {"MALCOLM"}, t = "All swoln and ulcerous, pitiful to the eye," },
    { r = {"MALCOLM"}, t = "The mere despair of surgery, he cures;" },
    { r = {"MALCOLM"}, t = "Hanging a golden stamp about their necks," },
    { r = {"MALCOLM"}, t = "Put on with holy prayers: and ’tis spoken," },
    { r = {"MALCOLM"}, t = "To the succeeding royalty he leaves" },
    { r = {"MALCOLM"}, t = "The healing benediction. With this strange virtue," },
    { r = {"MALCOLM"}, t = "He hath a heavenly gift of prophecy;" },
    { r = {"MALCOLM"}, t = "And sundry blessings hang about his throne," },
    { r = {"MALCOLM"}, t = "That speak him full of grace." },
    { d = "Enter Ross" },
    { r = {"MACDUFF"}, t = "See, who comes here?" },
    { r = {"MALCOLM"}, t = "My countryman; but yet I know him not." },
    { r = {"MACDUFF"}, t = "My ever-gentle cousin, welcome hither." },
    { r = {"MALCOLM"}, t = "I know him now. Good God, betimes remove" },
    { r = {"MALCOLM"}, t = "The means that makes us strangers!" },
    { r = {"ROSS"}, t = "Sir, amen." },
    { r = {"MACDUFF"}, t = "Stands Scotland where it did?" },
    { r = {"ROSS"}, t = "Alas, poor country," },
    { r = {"ROSS"}, t = "Almost afraid to know itself! It cannot" },
    { r = {"ROSS"}, t = "Be call’d our mother, but our grave, where nothing," },
    { r = {"ROSS"}, t = "But who knows nothing, is once seen to smile;" },
    { r = {"ROSS"}, t = "Where sighs, and groans, and shrieks, that rent the air," },
    { r = {"ROSS"}, t = "Are made, not mark’d; where violent sorrow seems" },
    { r = {"ROSS"}, t = "A modern ecstasy. The dead man’s knell" },
    { r = {"ROSS"}, t = "Is there scarce ask’d for who; and good men’s lives" },
    { r = {"ROSS"}, t = "Expire before the flowers in their caps," },
    { r = {"ROSS"}, t = "Dying or ere they sicken." },
    { r = {"MACDUFF"}, t = "O, relation" },
    { r = {"MACDUFF"}, t = "Too nice, and yet too true!" },
    { r = {"MALCOLM"}, t = "What’s the newest grief?" },
    { r = {"ROSS"}, t = "That of an hour’s age doth hiss the speaker;" },
    { r = {"ROSS"}, t = "Each minute teems a new one." },
    { r = {"MACDUFF"}, t = "How does my wife?" },
    { r = {"ROSS"}, t = "Why, well." },
    { r = {"MACDUFF"}, t = "And all my children?" },
    { r = {"ROSS"}, t = "Well too." },
    { r = {"MACDUFF"}, t = "The tyrant has not batter’d at their peace?" },
    { r = {"ROSS"}, t = "No; they were well at peace when I did leave ’em." },
    { r = {"MACDUFF"}, t = "Be not a niggard of your speech: how goes’t?" },
    { r = {"ROSS"}, t = "When I came hither to transport the tidings," },
    { r = {"ROSS"}, t = "Which I have heavily borne, there ran a rumour" },
    { r = {"ROSS"}, t = "Of many worthy fellows that were out;" },
    { r = {"ROSS"}, t = "Which was to my belief witness’d the rather," },
    { r = {"ROSS"}, t = "For that I saw the tyrant’s power afoot." },
    { r = {"ROSS"}, t = "Now is the time of help. Your eye in Scotland" },
    { r = {"ROSS"}, t = "Would create soldiers, make our women fight," },
    { r = {"ROSS"}, t = "To doff their dire distresses." },
    { r = {"MALCOLM"}, t = "Be’t their comfort" },
    { r = {"MALCOLM"}, t = "We are coming thither. Gracious England hath" },
    { r = {"MALCOLM"}, t = "Lent us good Siward and ten thousand men;" },
    { r = {"MALCOLM"}, t = "An older and a better soldier none" },
    { r = {"MALCOLM"}, t = "That Christendom gives out." },
    { r = {"ROSS"}, t = "Would I could answer" },
    { r = {"ROSS"}, t = "This comfort with the like! But I have words" },
    { r = {"ROSS"}, t = "That would be howl’d out in the desert air," },
    { r = {"ROSS"}, t = "Where hearing should not latch them." },
    { r = {"MACDUFF"}, t = "What concern they?" },
    { r = {"MACDUFF"}, t = "The general cause? or is it a fee-grief" },
    { r = {"MACDUFF"}, t = "Due to some single breast?" },
    { r = {"ROSS"}, t = "No mind that’s honest" },
    { r = {"ROSS"}, t = "But in it shares some woe, though the main part" },
    { r = {"ROSS"}, t = "Pertains to you alone." },
    { r = {"MACDUFF"}, t = "If it be mine," },
    { r = {"MACDUFF"}, t = "Keep it not from me, quickly let me have it." },
    { r = {"ROSS"}, t = "Let not your ears despise my tongue for ever," },
    { r = {"ROSS"}, t = "Which shall possess them with the heaviest sound" },
    { r = {"ROSS"}, t = "That ever yet they heard." },
    { r = {"MACDUFF"}, t = "Humh! I guess at it." },
    { r = {"ROSS"}, t = "Your castle is surpris’d; your wife and babes" },
    { r = {"ROSS"}, t = "Savagely slaughter’d. To relate the manner" },
    { r = {"ROSS"}, t = "Were, on the quarry of these murder’d deer," },
    { r = {"ROSS"}, t = "To add the death of you." },
    { r = {"MALCOLM"}, t = "Merciful heaven!—" },
    { r = {"MALCOLM"}, t = "What, man! ne’er pull your hat upon your brows." },
    { r = {"MALCOLM"}, t = "Give sorrow words. The grief that does not speak" },
    { r = {"MALCOLM"}, t = "Whispers the o’er-fraught heart, and bids it break." },
    { r = {"MACDUFF"}, t = "My children too?" },
    { r = {"ROSS"}, t = "Wife, children, servants, all" },
    { r = {"ROSS"}, t = "That could be found." },
    { r = {"MACDUFF"}, t = "And I must be from thence!" },
    { r = {"MACDUFF"}, t = "My wife kill’d too?" },
    { r = {"ROSS"}, t = "I have said." },
    { r = {"MALCOLM"}, t = "Be comforted:" },
    { r = {"MALCOLM"}, t = "Let’s make us med’cines of our great revenge," },
    { r = {"MALCOLM"}, t = "To cure this deadly grief." },
    { r = {"MACDUFF"}, t = "He has no children.—All my pretty ones?" },
    { r = {"MACDUFF"}, t = "Did you say all?—O hell-kite!—All?" },
    { r = {"MACDUFF"}, t = "What, all my pretty chickens and their dam" },
    { r = {"MACDUFF"}, t = "At one fell swoop?" },
    { r = {"MALCOLM"}, t = "Dispute it like a man." },
    { r = {"MACDUFF"}, t = "I shall do so;" },
    { r = {"MACDUFF"}, t = "But I must also feel it as a man:" },
    { r = {"MACDUFF"}, t = "I cannot but remember such things were," },
    { r = {"MACDUFF"}, t = "That were most precious to me.—Did heaven look on," },
    { r = {"MACDUFF"}, t = "And would not take their part? Sinful Macduff," },
    { r = {"MACDUFF"}, t = "They were all struck for thee! Naught that I am," },
    { r = {"MACDUFF"}, t = "Not for their own demerits, but for mine," },
    { r = {"MACDUFF"}, t = "Fell slaughter on their souls: heaven rest them now!" },
    { r = {"MALCOLM"}, t = "Be this the whetstone of your sword. Let grief" },
    { r = {"MALCOLM"}, t = "Convert to anger; blunt not the heart, enrage it." },
    { r = {"MACDUFF"}, t = "O, I could play the woman with mine eyes," },
    { r = {"MACDUFF"}, t = "And braggart with my tongue!—But, gentle heavens," },
    { r = {"MACDUFF"}, t = "Cut short all intermission; front to front," },
    { r = {"MACDUFF"}, t = "Bring thou this fiend of Scotland and myself;" },
    { r = {"MACDUFF"}, t = "Within my sword’s length set him; if he ’scape," },
    { r = {"MACDUFF"}, t = "Heaven forgive him too!" },
    { r = {"MALCOLM"}, t = "This tune goes manly." },
    { r = {"MALCOLM"}, t = "Come, go we to the King. Our power is ready;" },
    { r = {"MALCOLM"}, t = "Our lack is nothing but our leave. Macbeth" },
    { r = {"MALCOLM"}, t = "Is ripe for shaking, and the powers above" },
    { r = {"MALCOLM"}, t = "Put on their instruments. Receive what cheer you may;" },
    { r = {"MALCOLM"}, t = "The night is long that never finds the day." },
    { d = "Exeunt" },
    { d = "Act 5, Scene 1. Dunsinane. A Room in the Castle.", h = true },
    { d = "Enter a Doctor of Physic and a Waiting-Gentlewoman" },
    { r = {"DOCTOR"}, t = "I have two nights watched with you, but can perceive no truth in your report." },
    { r = {"DOCTOR"}, t = "When was it she last walked?" },
    { r = {"GENTLEWOMAN"}, t = "Since his Majesty went into the field, I have seen her rise from her bed, throw her nightgown upon her, unlock her closet, take forth paper, fold it, write upon’t, read it, afterwards seal it, and again return to bed;" },
    { r = {"GENTLEWOMAN"}, t = "yet all this while in a most fast sleep." },
    { r = {"DOCTOR"}, t = "A great perturbation in nature, to receive at once the benefit of sleep, and do the effects of watching." },
    { r = {"DOCTOR"}, t = "In this slumbery agitation, besides her walking and other actual performances, what, at any time, have you heard her say?" },
    { r = {"GENTLEWOMAN"}, t = "That, sir, which I will not report after her." },
    { r = {"DOCTOR"}, t = "You may to me; and ’tis most meet you should." },
    { r = {"GENTLEWOMAN"}, t = "Neither to you nor anyone; having no witness to confirm my speech." },
    { d = "Enter Lady Macbeth with a taper" },
    { r = {"GENTLEWOMAN"}, t = "Lo you, here she comes!" },
    { r = {"GENTLEWOMAN"}, t = "This is her very guise; and, upon my life, fast asleep." },
    { r = {"GENTLEWOMAN"}, t = "Observe her; stand close." },
    { r = {"DOCTOR"}, t = "How came she by that light?" },
    { r = {"GENTLEWOMAN"}, t = "Why, it stood by her: she has light by her continually; ’tis her command." },
    { r = {"DOCTOR"}, t = "You see, her eyes are open." },
    { r = {"GENTLEWOMAN"}, t = "Ay, but their sense are shut." },
    { r = {"DOCTOR"}, t = "What is it she does now? Look how she rubs her hands." },
    { r = {"GENTLEWOMAN"}, t = "It is an accustomed action with her, to seem thus washing her hands." },
    { r = {"GENTLEWOMAN"}, t = "I have known her continue in this a quarter of an hour." },
    { r = {"LADY MACBETH"}, t = "Yet here’s a spot." },
    { r = {"DOCTOR"}, t = "Hark, she speaks." },
    { r = {"DOCTOR"}, t = "I will set down what comes from her, to satisfy my remembrance the more strongly." },
    { r = {"LADY MACBETH"}, t = "Out, damned spot! out, I say! One; two. Why, then ’tis time to do’t." },
    { r = {"LADY MACBETH"}, t = "Hell is murky!" },
    { r = {"LADY MACBETH"}, t = "Fie, my lord, fie! a soldier, and afeard?" },
    { r = {"LADY MACBETH"}, t = "What need we fear who knows it, when none can call our power to account?" },
    { r = {"LADY MACBETH"}, t = "Yet who would have thought the old man to have had so much blood in him?" },
    { r = {"DOCTOR"}, t = "Do you mark that?" },
    { r = {"LADY MACBETH"}, t = "The Thane of Fife had a wife." },
    { r = {"LADY MACBETH"}, t = "Where is she now?—What, will these hands ne’er be clean?" },
    { r = {"LADY MACBETH"}, t = "No more o’ that, my lord, no more o’ that: you mar all with this starting." },
    { r = {"DOCTOR"}, t = "Go to, go to. You have known what you should not." },
    { r = {"GENTLEWOMAN"}, t = "She has spoke what she should not, I am sure of that: heaven knows what she has known." },
    { r = {"LADY MACBETH"}, t = "Here’s the smell of the blood still: all the perfumes of Arabia will not sweeten this little hand." },
    { r = {"LADY MACBETH"}, t = "Oh, oh, oh!" },
    { r = {"DOCTOR"}, t = "What a sigh is there! The heart is sorely charged." },
    { r = {"GENTLEWOMAN"}, t = "I would not have such a heart in my bosom for the dignity of the whole body." },
    { r = {"DOCTOR"}, t = "Well, well, well." },
    { r = {"GENTLEWOMAN"}, t = "Pray God it be, sir." },
    { r = {"DOCTOR"}, t = "This disease is beyond my practice: yet I have known those which have walked in their sleep, who have died holily in their beds." },
    { r = {"LADY MACBETH"}, t = "Wash your hands, put on your nightgown; look not so pale." },
    { r = {"LADY MACBETH"}, t = "I tell you yet again, Banquo’s buried; he cannot come out on’s grave." },
    { r = {"DOCTOR"}, t = "Even so?" },
    { r = {"LADY MACBETH"}, t = "To bed, to bed." },
    { r = {"LADY MACBETH"}, t = "There’s knocking at the gate." },
    { r = {"LADY MACBETH"}, t = "Come, come, come, come, give me your hand." },
    { r = {"LADY MACBETH"}, t = "What’s done cannot be undone." },
    { r = {"LADY MACBETH"}, t = "To bed, to bed, to bed." },
    { d = "Exit" },
    { r = {"DOCTOR"}, t = "Will she go now to bed?" },
    { r = {"GENTLEWOMAN"}, t = "Directly." },
    { r = {"DOCTOR"}, t = "Foul whisp’rings are abroad. Unnatural deeds" },
    { r = {"DOCTOR"}, t = "Do breed unnatural troubles: infected minds" },
    { r = {"DOCTOR"}, t = "To their deaf pillows will discharge their secrets." },
    { r = {"DOCTOR"}, t = "More needs she the divine than the physician.—" },
    { r = {"DOCTOR"}, t = "God, God, forgive us all! Look after her;" },
    { r = {"DOCTOR"}, t = "Remove from her the means of all annoyance," },
    { r = {"DOCTOR"}, t = "And still keep eyes upon her. So, good night:" },
    { r = {"DOCTOR"}, t = "My mind she has mated, and amaz’d my sight." },
    { r = {"DOCTOR"}, t = "I think, but dare not speak." },
    { r = {"GENTLEWOMAN"}, t = "Good night, good doctor." },
    { d = "Exeunt" },
    { d = "Act 5, Scene 2. The Country near Dunsinane.", h = true },
    { d = "Enter, with drum and colours Menteith, Caithness, Angus, Lennox and Soldiers" },
    { r = {"MENTEITH"}, t = "The English power is near, led on by Malcolm," },
    { r = {"MENTEITH"}, t = "His uncle Siward, and the good Macduff." },
    { r = {"MENTEITH"}, t = "Revenges burn in them; for their dear causes" },
    { r = {"MENTEITH"}, t = "Would to the bleeding and the grim alarm" },
    { r = {"MENTEITH"}, t = "Excite the mortified man." },
    { r = {"ANGUS"}, t = "Near Birnam wood" },
    { r = {"ANGUS"}, t = "Shall we well meet them. That way are they coming." },
    { r = {"CAITHNESS"}, t = "Who knows if Donalbain be with his brother?" },
    { r = {"LENNOX"}, t = "For certain, sir, he is not. I have a file" },
    { r = {"LENNOX"}, t = "Of all the gentry: there is Siward’s son" },
    { r = {"LENNOX"}, t = "And many unrough youths, that even now" },
    { r = {"LENNOX"}, t = "Protest their first of manhood." },
    { r = {"MENTEITH"}, t = "What does the tyrant?" },
    { r = {"CAITHNESS"}, t = "Great Dunsinane he strongly fortifies." },
    { r = {"CAITHNESS"}, t = "Some say he’s mad; others, that lesser hate him," },
    { r = {"CAITHNESS"}, t = "Do call it valiant fury: but, for certain," },
    { r = {"CAITHNESS"}, t = "He cannot buckle his distemper’d cause" },
    { r = {"CAITHNESS"}, t = "Within the belt of rule." },
    { r = {"ANGUS"}, t = "Now does he feel" },
    { r = {"ANGUS"}, t = "His secret murders sticking on his hands;" },
    { r = {"ANGUS"}, t = "Now minutely revolts upbraid his faith-breach;" },
    { r = {"ANGUS"}, t = "Those he commands move only in command," },
    { r = {"ANGUS"}, t = "Nothing in love: now does he feel his title" },
    { r = {"ANGUS"}, t = "Hang loose about him, like a giant’s robe" },
    { r = {"ANGUS"}, t = "Upon a dwarfish thief." },
    { r = {"MENTEITH"}, t = "Who, then, shall blame" },
    { r = {"MENTEITH"}, t = "His pester’d senses to recoil and start," },
    { r = {"MENTEITH"}, t = "When all that is within him does condemn" },
    { r = {"MENTEITH"}, t = "Itself for being there?" },
    { r = {"CAITHNESS"}, t = "Well, march we on," },
    { r = {"CAITHNESS"}, t = "To give obedience where ’tis truly ow’d:" },
    { r = {"CAITHNESS"}, t = "Meet we the med’cine of the sickly weal;" },
    { r = {"CAITHNESS"}, t = "And with him pour we, in our country’s purge," },
    { r = {"CAITHNESS"}, t = "Each drop of us." },
    { r = {"LENNOX"}, t = "Or so much as it needs" },
    { r = {"LENNOX"}, t = "To dew the sovereign flower, and drown the weeds." },
    { r = {"LENNOX"}, t = "Make we our march towards Birnam." },
    { d = "Exeunt, marching" },
    { d = "Act 5, Scene 3. Dunsinane. A Room in the Castle.", h = true },
    { d = "Enter Macbeth, Doctor and Attendants" },
    { r = {"MACBETH"}, t = "Bring me no more reports; let them fly all:" },
    { r = {"MACBETH"}, t = "Till Birnam wood remove to Dunsinane" },
    { r = {"MACBETH"}, t = "I cannot taint with fear. What’s the boy Malcolm?" },
    { r = {"MACBETH"}, t = "Was he not born of woman? The spirits that know" },
    { r = {"MACBETH"}, t = "All mortal consequences have pronounc’d me thus:" },
    { r = {"MACBETH"}, t = "“Fear not, Macbeth; no man that’s born of woman" },
    { r = {"MACBETH"}, t = "Shall e’er have power upon thee.”—Then fly, false thanes," },
    { r = {"MACBETH"}, t = "And mingle with the English epicures:" },
    { r = {"MACBETH"}, t = "The mind I sway by, and the heart I bear," },
    { r = {"MACBETH"}, t = "Shall never sag with doubt nor shake with fear." },
    { d = "Enter a Servant" },
    { r = {"MACBETH"}, t = "The devil damn thee black, thou cream-fac’d loon!" },
    { r = {"MACBETH"}, t = "Where gott’st thou that goose look?" },
    { r = {"SERVANT"}, t = "There is ten thousand" },
    { r = {"MACBETH"}, t = "Geese, villain?" },
    { r = {"SERVANT"}, t = "Soldiers, sir." },
    { r = {"MACBETH"}, t = "Go prick thy face and over-red thy fear," },
    { r = {"MACBETH"}, t = "Thou lily-liver’d boy. What soldiers, patch?" },
    { r = {"MACBETH"}, t = "Death of thy soul! those linen cheeks of thine" },
    { r = {"MACBETH"}, t = "Are counsellors to fear. What soldiers, whey-face?" },
    { r = {"SERVANT"}, t = "The English force, so please you." },
    { r = {"MACBETH"}, t = "Take thy face hence." },
    { d = "Exit Servant" },
    { r = {"MACBETH"}, t = "Seyton!—I am sick at heart," },
    { r = {"MACBETH"}, t = "When I behold—Seyton, I say!—This push" },
    { r = {"MACBETH"}, t = "Will cheer me ever or disseat me now." },
    { r = {"MACBETH"}, t = "I have liv’d long enough: my way of life" },
    { r = {"MACBETH"}, t = "Is fall’n into the sere, the yellow leaf;" },
    { r = {"MACBETH"}, t = "And that which should accompany old age," },
    { r = {"MACBETH"}, t = "As honour, love, obedience, troops of friends," },
    { r = {"MACBETH"}, t = "I must not look to have; but, in their stead," },
    { r = {"MACBETH"}, t = "Curses, not loud but deep, mouth-honour, breath," },
    { r = {"MACBETH"}, t = "Which the poor heart would fain deny, and dare not." },
    { r = {"MACBETH"}, t = "Seyton!" },
    { d = "Enter Seyton" },
    { r = {"SEYTON"}, t = "What’s your gracious pleasure?" },
    { r = {"MACBETH"}, t = "What news more?" },
    { r = {"SEYTON"}, t = "All is confirm’d, my lord, which was reported." },
    { r = {"MACBETH"}, t = "I’ll fight till from my bones my flesh be hack’d." },
    { r = {"MACBETH"}, t = "Give me my armour." },
    { r = {"SEYTON"}, t = "’Tis not needed yet." },
    { r = {"MACBETH"}, t = "I’ll put it on." },
    { r = {"MACBETH"}, t = "Send out more horses, skirr the country round;" },
    { r = {"MACBETH"}, t = "Hang those that talk of fear. Give me mine armour.—" },
    { r = {"MACBETH"}, t = "How does your patient, doctor?" },
    { r = {"DOCTOR"}, t = "Not so sick, my lord," },
    { r = {"DOCTOR"}, t = "As she is troubled with thick-coming fancies," },
    { r = {"DOCTOR"}, t = "That keep her from her rest." },
    { r = {"MACBETH"}, t = "Cure her of that:" },
    { r = {"MACBETH"}, t = "Canst thou not minister to a mind diseas’d," },
    { r = {"MACBETH"}, t = "Pluck from the memory a rooted sorrow," },
    { r = {"MACBETH"}, t = "Raze out the written troubles of the brain," },
    { r = {"MACBETH"}, t = "And with some sweet oblivious antidote" },
    { r = {"MACBETH"}, t = "Cleanse the stuff’d bosom of that perilous stuff" },
    { r = {"MACBETH"}, t = "Which weighs upon the heart?" },
    { r = {"DOCTOR"}, t = "Therein the patient" },
    { r = {"DOCTOR"}, t = "Must minister to himself." },
    { r = {"MACBETH"}, t = "Throw physic to the dogs, I’ll none of it." },
    { r = {"MACBETH"}, t = "Come, put mine armour on; give me my staff:" },
    { r = {"MACBETH"}, t = "Seyton, send out.—Doctor, the Thanes fly from me.—" },
    { r = {"MACBETH"}, t = "Come, sir, despatch.—If thou couldst, doctor, cast" },
    { r = {"MACBETH"}, t = "The water of my land, find her disease," },
    { r = {"MACBETH"}, t = "And purge it to a sound and pristine health," },
    { r = {"MACBETH"}, t = "I would applaud thee to the very echo," },
    { r = {"MACBETH"}, t = "That should applaud again.—Pull’t off, I say.—" },
    { r = {"MACBETH"}, t = "What rhubarb, senna, or what purgative drug," },
    { r = {"MACBETH"}, t = "Would scour these English hence? Hear’st thou of them?" },
    { r = {"DOCTOR"}, t = "Ay, my good lord. Your royal preparation" },
    { r = {"DOCTOR"}, t = "Makes us hear something." },
    { r = {"MACBETH"}, t = "Bring it after me.—" },
    { r = {"MACBETH"}, t = "I will not be afraid of death and bane," },
    { r = {"MACBETH"}, t = "Till Birnam forest come to Dunsinane." },
    { d = "Exeunt all except Doctor" },
    { r = {"DOCTOR"}, t = "Were I from Dunsinane away and clear," },
    { r = {"DOCTOR"}, t = "Profit again should hardly draw me here." },
    { d = "Exit" },
    { d = "Act 5, Scene 4. Country near Dunsinane: a Wood in view.", h = true },
    { d = "Enter, with drum and colours Malcolm, old Siward and his Son, Macduff, Menteith, Caithness, Angus, Lennox, Ross and Soldiers, marching" },
    { r = {"MALCOLM"}, t = "Cousins, I hope the days are near at hand" },
    { r = {"MALCOLM"}, t = "That chambers will be safe." },
    { r = {"MENTEITH"}, t = "We doubt it nothing." },
    { r = {"SIWARD"}, t = "What wood is this before us?" },
    { r = {"MENTEITH"}, t = "The wood of Birnam." },
    { r = {"MALCOLM"}, t = "Let every soldier hew him down a bough," },
    { r = {"MALCOLM"}, t = "And bear’t before him. Thereby shall we shadow" },
    { r = {"MALCOLM"}, t = "The numbers of our host, and make discovery" },
    { r = {"MALCOLM"}, t = "Err in report of us." },
    { r = {"SOLDIERS"}, t = "It shall be done." },
    { r = {"SIWARD"}, t = "We learn no other but the confident tyrant" },
    { r = {"SIWARD"}, t = "Keeps still in Dunsinane, and will endure" },
    { r = {"SIWARD"}, t = "Our setting down before’t." },
    { r = {"MALCOLM"}, t = "’Tis his main hope;" },
    { r = {"MALCOLM"}, t = "For where there is advantage to be given," },
    { r = {"MALCOLM"}, t = "Both more and less have given him the revolt," },
    { r = {"MALCOLM"}, t = "And none serve with him but constrained things," },
    { r = {"MALCOLM"}, t = "Whose hearts are absent too." },
    { r = {"MACDUFF"}, t = "Let our just censures" },
    { r = {"MACDUFF"}, t = "Attend the true event, and put we on" },
    { r = {"MACDUFF"}, t = "Industrious soldiership." },
    { r = {"SIWARD"}, t = "The time approaches," },
    { r = {"SIWARD"}, t = "That will with due decision make us know" },
    { r = {"SIWARD"}, t = "What we shall say we have, and what we owe." },
    { r = {"SIWARD"}, t = "Thoughts speculative their unsure hopes relate," },
    { r = {"SIWARD"}, t = "But certain issue strokes must arbitrate;" },
    { r = {"SIWARD"}, t = "Towards which advance the war." },
    { d = "Exeunt, marching" },
    { d = "Act 5, Scene 5. Dunsinane. Within the castle.", h = true },
    { d = "Enter with drum and colours, Macbeth, Seyton and Soldiers" },
    { r = {"MACBETH"}, t = "Hang out our banners on the outward walls;" },
    { r = {"MACBETH"}, t = "The cry is still, “They come!” Our castle’s strength" },
    { r = {"MACBETH"}, t = "Will laugh a siege to scorn: here let them lie" },
    { r = {"MACBETH"}, t = "Till famine and the ague eat them up." },
    { r = {"MACBETH"}, t = "Were they not forc’d with those that should be ours," },
    { r = {"MACBETH"}, t = "We might have met them dareful, beard to beard," },
    { r = {"MACBETH"}, t = "And beat them backward home." },
    { d = "A cry of women within" },
    { r = {"MACBETH"}, t = "What is that noise?" },
    { r = {"SEYTON"}, t = "It is the cry of women, my good lord." },
    { d = "Exit" },
    { r = {"MACBETH"}, t = "I have almost forgot the taste of fears." },
    { r = {"MACBETH"}, t = "The time has been, my senses would have cool’d" },
    { r = {"MACBETH"}, t = "To hear a night-shriek; and my fell of hair" },
    { r = {"MACBETH"}, t = "Would at a dismal treatise rouse and stir" },
    { r = {"MACBETH"}, t = "As life were in’t. I have supp’d full with horrors;" },
    { r = {"MACBETH"}, t = "Direness, familiar to my slaughterous thoughts," },
    { r = {"MACBETH"}, t = "Cannot once start me." },
    { d = "Enter Seyton" },
    { r = {"MACBETH"}, t = "Wherefore was that cry?" },
    { r = {"SEYTON"}, t = "The Queen, my lord, is dead." },
    { r = {"MACBETH"}, t = "She should have died hereafter." },
    { r = {"MACBETH"}, t = "There would have been a time for such a word." },
    { r = {"MACBETH"}, t = "Tomorrow, and tomorrow, and tomorrow," },
    { r = {"MACBETH"}, t = "Creeps in this petty pace from day to day," },
    { r = {"MACBETH"}, t = "To the last syllable of recorded time;" },
    { r = {"MACBETH"}, t = "And all our yesterdays have lighted fools" },
    { r = {"MACBETH"}, t = "The way to dusty death. Out, out, brief candle!" },
    { r = {"MACBETH"}, t = "Life’s but a walking shadow; a poor player," },
    { r = {"MACBETH"}, t = "That struts and frets his hour upon the stage," },
    { r = {"MACBETH"}, t = "And then is heard no more: it is a tale" },
    { r = {"MACBETH"}, t = "Told by an idiot, full of sound and fury," },
    { r = {"MACBETH"}, t = "Signifying nothing." },
    { d = "Enter a Messenger" },
    { r = {"MACBETH"}, t = "Thou com’st to use thy tongue; thy story quickly." },
    { r = {"MESSENGER"}, t = "Gracious my lord," },
    { r = {"MESSENGER"}, t = "I should report that which I say I saw," },
    { r = {"MESSENGER"}, t = "But know not how to do’t." },
    { r = {"MACBETH"}, t = "Well, say, sir." },
    { r = {"MESSENGER"}, t = "As I did stand my watch upon the hill," },
    { r = {"MESSENGER"}, t = "I look’d toward Birnam, and anon, methought," },
    { r = {"MESSENGER"}, t = "The wood began to move." },
    { r = {"MACBETH"}, t = "Liar, and slave!" },
    { r = {"MESSENGER"}, t = "Let me endure your wrath, if’t be not so." },
    { r = {"MESSENGER"}, t = "Within this three mile may you see it coming;" },
    { r = {"MESSENGER"}, t = "I say, a moving grove." },
    { r = {"MACBETH"}, t = "If thou speak’st false," },
    { r = {"MACBETH"}, t = "Upon the next tree shalt thou hang alive," },
    { r = {"MACBETH"}, t = "Till famine cling thee: if thy speech be sooth," },
    { r = {"MACBETH"}, t = "I care not if thou dost for me as much.—" },
    { r = {"MACBETH"}, t = "I pull in resolution; and begin" },
    { r = {"MACBETH"}, t = "To doubt th’ equivocation of the fiend," },
    { r = {"MACBETH"}, t = "That lies like truth. “Fear not, till Birnam wood" },
    { r = {"MACBETH"}, t = "Do come to Dunsinane;” and now a wood" },
    { r = {"MACBETH"}, t = "Comes toward Dunsinane.—Arm, arm, and out!—" },
    { r = {"MACBETH"}, t = "If this which he avouches does appear," },
    { r = {"MACBETH"}, t = "There is nor flying hence nor tarrying here." },
    { r = {"MACBETH"}, t = "I ’gin to be aweary of the sun," },
    { r = {"MACBETH"}, t = "And wish th’ estate o’ th’ world were now undone.—" },
    { r = {"MACBETH"}, t = "Ring the alarum bell!—Blow, wind! come, wrack!" },
    { r = {"MACBETH"}, t = "At least we’ll die with harness on our back." },
    { d = "Exeunt" },
    { d = "Act 5, Scene 6. The same. A Plain before the Castle.", h = true },
    { d = "Enter, with drum and colours, Malcolm, old Siward, Macduff and their Army, with boughs" },
    { r = {"MALCOLM"}, t = "Now near enough. Your leafy screens throw down," },
    { r = {"MALCOLM"}, t = "And show like those you are.—You, worthy uncle," },
    { r = {"MALCOLM"}, t = "Shall with my cousin, your right noble son," },
    { r = {"MALCOLM"}, t = "Lead our first battle: worthy Macduff and we" },
    { r = {"MALCOLM"}, t = "Shall take upon’s what else remains to do," },
    { r = {"MALCOLM"}, t = "According to our order." },
    { r = {"SIWARD"}, t = "Fare you well.—" },
    { r = {"SIWARD"}, t = "Do we but find the tyrant’s power tonight," },
    { r = {"SIWARD"}, t = "Let us be beaten, if we cannot fight." },
    { r = {"MACDUFF"}, t = "Make all our trumpets speak; give them all breath," },
    { r = {"MACDUFF"}, t = "Those clamorous harbingers of blood and death." },
    { d = "Exeunt" },
    { d = "Act 5, Scene 7. The same. Another part of the Plain.", h = true },
    { d = "Alarums. Enter Macbeth" },
    { r = {"MACBETH"}, t = "They have tied me to a stake. I cannot fly," },
    { r = {"MACBETH"}, t = "But, bear-like I must fight the course.—What’s he" },
    { r = {"MACBETH"}, t = "That was not born of woman? Such a one" },
    { r = {"MACBETH"}, t = "Am I to fear, or none." },
    { d = "Enter young Siward" },
    { r = {"YOUNG SIWARD"}, t = "What is thy name?" },
    { r = {"MACBETH"}, t = "Thou’lt be afraid to hear it." },
    { r = {"YOUNG SIWARD"}, t = "No; though thou call’st thyself a hotter name" },
    { r = {"YOUNG SIWARD"}, t = "Than any is in hell." },
    { r = {"MACBETH"}, t = "My name’s Macbeth." },
    { r = {"YOUNG SIWARD"}, t = "The devil himself could not pronounce a title" },
    { r = {"YOUNG SIWARD"}, t = "More hateful to mine ear." },
    { r = {"MACBETH"}, t = "No, nor more fearful." },
    { r = {"YOUNG SIWARD"}, t = "Thou liest, abhorred tyrant. With my sword" },
    { r = {"YOUNG SIWARD"}, t = "I’ll prove the lie thou speak’st." },
    { d = "They fight, and young Siward is slain" },
    { r = {"MACBETH"}, t = "Thou wast born of woman." },
    { r = {"MACBETH"}, t = "But swords I smile at, weapons laugh to scorn," },
    { r = {"MACBETH"}, t = "Brandish’d by man that’s of a woman born." },
    { d = "Exit" },
    { d = "Alarums. Enter Macduff" },
    { r = {"MACDUFF"}, t = "That way the noise is.—Tyrant, show thy face!" },
    { r = {"MACDUFF"}, t = "If thou be’st slain and with no stroke of mine," },
    { r = {"MACDUFF"}, t = "My wife and children’s ghosts will haunt me still." },
    { r = {"MACDUFF"}, t = "I cannot strike at wretched kerns, whose arms" },
    { r = {"MACDUFF"}, t = "Are hired to bear their staves. Either thou, Macbeth," },
    { r = {"MACDUFF"}, t = "Or else my sword, with an unbatter’d edge," },
    { r = {"MACDUFF"}, t = "I sheathe again undeeded. There thou shouldst be;" },
    { r = {"MACDUFF"}, t = "By this great clatter, one of greatest note" },
    { r = {"MACDUFF"}, t = "Seems bruited. Let me find him, Fortune!" },
    { r = {"MACDUFF"}, t = "And more I beg not." },
    { d = "Exit. Alarums" },
    { d = "Enter Malcolm and old Siward" },
    { r = {"SIWARD"}, t = "This way, my lord;—the castle’s gently render’d:" },
    { r = {"SIWARD"}, t = "The tyrant’s people on both sides do fight;" },
    { r = {"SIWARD"}, t = "The noble thanes do bravely in the war," },
    { r = {"SIWARD"}, t = "The day almost itself professes yours," },
    { r = {"SIWARD"}, t = "And little is to do." },
    { r = {"MALCOLM"}, t = "We have met with foes" },
    { r = {"MALCOLM"}, t = "That strike beside us." },
    { r = {"SIWARD"}, t = "Enter, sir, the castle." },
    { d = "Exeunt. Alarums" },
    { d = "Act 5, Scene 8. The same. Another part of the field.", h = true },
    { d = "Enter Macbeth" },
    { r = {"MACBETH"}, t = "Why should I play the Roman fool, and die" },
    { r = {"MACBETH"}, t = "On mine own sword? whiles I see lives, the gashes" },
    { r = {"MACBETH"}, t = "Do better upon them." },
    { d = "Enter Macduff" },
    { r = {"MACDUFF"}, t = "Turn, hell-hound, turn!" },
    { r = {"MACBETH"}, t = "Of all men else I have avoided thee:" },
    { r = {"MACBETH"}, t = "But get thee back; my soul is too much charg’d" },
    { r = {"MACBETH"}, t = "With blood of thine already." },
    { r = {"MACDUFF"}, t = "I have no words;" },
    { r = {"MACDUFF"}, t = "My voice is in my sword: thou bloodier villain" },
    { r = {"MACDUFF"}, t = "Than terms can give thee out!" },
    { d = "They fight" },
    { r = {"MACBETH"}, t = "Thou losest labour:" },
    { r = {"MACBETH"}, t = "As easy mayst thou the intrenchant air" },
    { r = {"MACBETH"}, t = "With thy keen sword impress, as make me bleed:" },
    { r = {"MACBETH"}, t = "Let fall thy blade on vulnerable crests;" },
    { r = {"MACBETH"}, t = "I bear a charmed life, which must not yield" },
    { r = {"MACBETH"}, t = "To one of woman born." },
    { r = {"MACDUFF"}, t = "Despair thy charm;" },
    { r = {"MACDUFF"}, t = "And let the angel whom thou still hast serv’d" },
    { r = {"MACDUFF"}, t = "Tell thee, Macduff was from his mother’s womb" },
    { r = {"MACDUFF"}, t = "Untimely ripp’d." },
    { r = {"MACBETH"}, t = "Accursed be that tongue that tells me so," },
    { r = {"MACBETH"}, t = "For it hath cow’d my better part of man!" },
    { r = {"MACBETH"}, t = "And be these juggling fiends no more believ’d," },
    { r = {"MACBETH"}, t = "That palter with us in a double sense;" },
    { r = {"MACBETH"}, t = "That keep the word of promise to our ear," },
    { r = {"MACBETH"}, t = "And break it to our hope!—I’ll not fight with thee." },
    { r = {"MACDUFF"}, t = "Then yield thee, coward," },
    { r = {"MACDUFF"}, t = "And live to be the show and gaze o’ th’ time." },
    { r = {"MACDUFF"}, t = "We’ll have thee, as our rarer monsters are," },
    { r = {"MACDUFF"}, t = "Painted upon a pole, and underwrit," },
    { r = {"MACDUFF"}, t = "“Here may you see the tyrant.”" },
    { r = {"MACBETH"}, t = "I will not yield," },
    { r = {"MACBETH"}, t = "To kiss the ground before young Malcolm’s feet," },
    { r = {"MACBETH"}, t = "And to be baited with the rabble’s curse." },
    { r = {"MACBETH"}, t = "Though Birnam wood be come to Dunsinane," },
    { r = {"MACBETH"}, t = "And thou oppos’d, being of no woman born," },
    { r = {"MACBETH"}, t = "Yet I will try the last. Before my body" },
    { r = {"MACBETH"}, t = "I throw my warlike shield: lay on, Macduff;" },
    { r = {"MACBETH"}, t = "And damn’d be him that first cries, “Hold, enough!”" },
    { d = "Exeunt fighting. Alarums" },
    { d = "Retreat. Flourish. Enter, with drum and colours, Malcolm, old Siward, Ross, Thanes and Soldiers" },
    { r = {"MALCOLM"}, t = "I would the friends we miss were safe arriv’d." },
    { r = {"SIWARD"}, t = "Some must go off; and yet, by these I see," },
    { r = {"SIWARD"}, t = "So great a day as this is cheaply bought." },
    { r = {"MALCOLM"}, t = "Macduff is missing, and your noble son." },
    { r = {"ROSS"}, t = "Your son, my lord, has paid a soldier’s debt:" },
    { r = {"ROSS"}, t = "He only liv’d but till he was a man;" },
    { r = {"ROSS"}, t = "The which no sooner had his prowess confirm’d" },
    { r = {"ROSS"}, t = "In the unshrinking station where he fought," },
    { r = {"ROSS"}, t = "But like a man he died." },
    { r = {"SIWARD"}, t = "Then he is dead?" },
    { r = {"ROSS"}, t = "Ay, and brought off the field. Your cause of sorrow" },
    { r = {"ROSS"}, t = "Must not be measur’d by his worth, for then" },
    { r = {"ROSS"}, t = "It hath no end." },
    { r = {"SIWARD"}, t = "Had he his hurts before?" },
    { r = {"ROSS"}, t = "Ay, on the front." },
    { r = {"SIWARD"}, t = "Why then, God’s soldier be he!" },
    { r = {"SIWARD"}, t = "Had I as many sons as I have hairs," },
    { r = {"SIWARD"}, t = "I would not wish them to a fairer death:" },
    { r = {"SIWARD"}, t = "And so his knell is knoll’d." },
    { r = {"MALCOLM"}, t = "He’s worth more sorrow," },
    { r = {"MALCOLM"}, t = "And that I’ll spend for him." },
    { r = {"SIWARD"}, t = "He’s worth no more." },
    { r = {"SIWARD"}, t = "They say he parted well and paid his score:" },
    { r = {"SIWARD"}, t = "And so, God be with him!—Here comes newer comfort." },
    { d = "Enter Macduff with Macbeth’s head" },
    { r = {"MACDUFF"}, t = "Hail, King, for so thou art. Behold, where stands" },
    { r = {"MACDUFF"}, t = "Th’ usurper’s cursed head: the time is free." },
    { r = {"MACDUFF"}, t = "I see thee compass’d with thy kingdom’s pearl," },
    { r = {"MACDUFF"}, t = "That speak my salutation in their minds;" },
    { r = {"MACDUFF"}, t = "Whose voices I desire aloud with mine,—" },
    { r = {"MACDUFF"}, t = "Hail, King of Scotland!" },
    { r = {"ALL"}, t = "Hail, King of Scotland!" },
    { d = "Flourish" },
    { r = {"MALCOLM"}, t = "We shall not spend a large expense of time" },
    { r = {"MALCOLM"}, t = "Before we reckon with your several loves," },
    { r = {"MALCOLM"}, t = "And make us even with you. My thanes and kinsmen," },
    { r = {"MALCOLM"}, t = "Henceforth be earls, the first that ever Scotland" },
    { r = {"MALCOLM"}, t = "In such an honour nam’d. What’s more to do," },
    { r = {"MALCOLM"}, t = "Which would be planted newly with the time,—" },
    { r = {"MALCOLM"}, t = "As calling home our exil’d friends abroad," },
    { r = {"MALCOLM"}, t = "That fled the snares of watchful tyranny;" },
    { r = {"MALCOLM"}, t = "Producing forth the cruel ministers" },
    { r = {"MALCOLM"}, t = "Of this dead butcher, and his fiend-like queen," },
    { r = {"MALCOLM"}, t = "Who, as ’tis thought, by self and violent hands" },
    { r = {"MALCOLM"}, t = "Took off her life;—this, and what needful else" },
    { r = {"MALCOLM"}, t = "That calls upon us, by the grace of Grace," },
    { r = {"MALCOLM"}, t = "We will perform in measure, time, and place." },
    { r = {"MALCOLM"}, t = "So thanks to all at once, and to each one," },
    { r = {"MALCOLM"}, t = "Whom we invite to see us crown’d at Scone." },
    { d = "Flourish. Exeunt" },
